INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('S1_LIT_P1', 'sohssure', 1, '문학', '어느 날, 작은 올챙이가 엄마 개구리에게 물었습니다.\n"엄마, 저는 언제 엄마처럼 될 수 있어요?"\n엄마 개구리는 웃으며 대답했습니다.\n"시간이 지나면 뒷다리가 쑥, 앞다리가 쑥 나올 거야. 그러면 꼬리는 점점 짧아지고 멋진 개구리가 된단다."\n올챙이는 매일매일 내 몸이 어떻게 변하는지 거울을 보며 기다렸습니다.\n며칠 뒤, 정말로 뒷다리가 조금씩 나오기 시작했습니다. 올챙이는 너무 기뻐서 연못을 헤엄쳐 다녔습니다.\n"야호! 나도 곧 개구리가 된다!"\n친구 물고기가 다가와 말했습니다.\n"축하해, 올챙이야. 하지만 개구리가 되면 우리랑 헤어져야 하니 조금 슬프네."\n올챙이는 잠시 생각에 잠기더니 말했습니다.\n"걱정 마. 내가 개구리가 되어도 자주 연못에 놀러 올게."');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('S1_LIT_P2', 'sohssure', 1, '문학', '(가)\n물 한 모금 입에 물고\n하늘 한 번 쳐다보고\n또 한 모금 입에 물고\n구름 한 번 쳐다보고\n\n- 강소천, <닭>\n\n(나)\n가자 가자 가자\n숲으로 가자\n달조각을 주우러\n숲으로 가자\n\n그믐밤 반딧불은\n부서진 달조각\n\n가자 가자 가자\n숲으로 가자\n달조각을 주우러\n숲으로 가자\n\n- 윤동주, <반딧불>');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('S1_LIT_P3', 'sohssure', 2, '문학', '[지문]\n(가)\n엄마야 누나야 강변 살자\n뜰에는 반짝이는 금모래 빛\n뒷문 밖에는 갈잎의 노래\n엄마야 누나야 강변 살자\n\n(나)\n푸른 하늘 은하수 하얀 쪽배에\n계수나무 한 나무 토끼 한 마리\n돛대도 아니 달고 삿대도 없이\n가기도 잘도 간다 서쪽 나라로\n\n은하수를 건너서 구름 나라로\n구름 나라 지나선 어디로 가나\n멀리서 반짝반짝 비치이는 건\n샛별이 등대란다 길을 찾아라');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('S1_LIT_P4', 'sohssure', 3, '문학', '[지문]\n(가)\n빨랫줄에 걸어 논\n요에다 그린 지도\n지난밤에 내 동생\n오줌 쏴 눈 지도.\n\n꿈에 가다 꿈에 가다\n돈 주워 넣고\n지난밤에 내 동생\n오줌 쏴 눈 지도.\n\n부엌 문 앞까지\n꿈에 가고\n아침에 일어나\n소금 얻으러 간 지도.\n\n(나)\n자주 꽃 핀 건\n자주 감자,\n파 보나 마나\n자주 감자.\n\n하얀 꽃 핀 건\n하얀 감자,\n파 보나 마나\n하얀 감자.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('S1_NON_P1', 'sohssure', 1, '비문학', '나비는 어떻게 자랄까요? 나비는 알, 애벌레, 번데기, 그리고 어른벌레(성충)라는 네 가지 단계를 거쳐요.\n먼저, 나비 엄마는 나뭇잎 뒷면에 작은 알을 낳아요. 며칠이 지나면 알에서 애벌레가 나와요. 애벌레는 나뭇잎을 아주 많이 먹고 쑥쑥 자라지요.\n몸이 충분히 커지면 애벌레는 입에서 실을 뽑아 몸을 감싸고 번데기가 되어요. 번데기는 꼼짝 않고 가만히 있는 것 같지만, 그 안에서는 놀라운 변화가 일어나고 있답니다.\n따뜻한 봄날이 되면 번데기 껍질이 갈라지고, 마침내 예쁜 날개를 가진 나비가 나와요. 처음에는 날개가 젖어 있어서 날 수 없지만, 햇볕에 날개를 말리면 하늘을 훨훨 날아다닐 수 있답니다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('S1_NON_P2', 'sohssure', 1, '비문학', '[지문]\n토끼는 귀가 길어요. 왜 그럴까요? 토끼는 숲속에서 약한 동물이에요. 그래서 적이 나타나면 빨리 도망가야 해요.\n토끼의 긴 귀는 아주 작은 소리도 잘 들을 수 있어요. 멀리서 무서운 호랑이나 늑대가 오는 소리를 빨리 듣고 피할 수 있지요.\n또 토끼의 귀는 더위를 식혀 주는 역할도 해요. 토끼는 땀을 흘리지 않아요. 대신 커다란 귀로 몸의 열을 밖으로 내보내요. 그래서 더운 여름에도 시원하게 지낼 수 있답니다.\n토끼의 귀는 정말 신기하지요? 단순히 소리만 듣는 것이 아니라, 토끼의 생명을 지켜 주는 아주 중요한 보물이에요.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('S1_NON_P3', 'sohssure', 2, '비문학', '[지문]\n하늘에 둥둥 떠 있는 구름은 어떻게 만들어질까요?\n강이나 바다에 있는 물은 햇볕을 받으면 김이 되어 하늘로 올라갑니다. 이것을 \'수증기\'라고 합니다. 수증기는 눈에 보이지 않을 만큼 아주 작고 가볍습니다. 하늘 높이 올라간 수증기는 찬 공기를 만나면 다시 아주 작은 물방울로 변합니다. 이 작은 물방울들이 많이 모여서 우리 눈에 보이는 것이 바로 \'구름\'입니다.\n\n구름 속에 있는 물방울들은 서로 부딪치면서 점점 커집니다. 그러다가 물방울이 너무 무거워지면 더 이상 하늘에 떠 있지 못하고 아래로 떨어지게 됩니다. 이것이 우리가 맞이하는 \'비\'입니다. 만약 날씨가 아주 추우면 물방울이 얼어서 하얀 \'눈\'이 되어 내리기도 합니다.\n\n이렇게 물은 돌고 돕니다. 바다에서 하늘로, 하늘에서 다시 땅으로, 그리고 땅에서 다시 바다로 여행을 하는 것입니다. 이 여행 덕분에 식물들도 무럭무럭 자라고 우리도 시원한 물을 마실 수 있답니다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('S1_NON_P4', 'sohssure', 3, '비문학', '[지문]\n자석은 참 신기한 물건입니다. 자석에는 N극과 S극이라는 두 극이 있습니다. N극은 북쪽을 가리키고, S극은 남쪽을 가리킵니다. 우리가 나침반을 이용해 길을 찾을 수 있는 것도 바로 이 성질 덕분입니다.\n\n자석은 서로 다른 극끼리는 끌어당기고, 같은 극끼리는 밀어내는 성질이 있습니다. N극과 S극이 만나면 착 달라붙지만, N극과 N극이 만나거나 S극과 S극이 만나면 서로 밀어냅니다.\n\n자석은 우리 생활 속에서도 많이 쓰입니다. 냉장고 문이 꽉 닫히는 것도 고무 패킹 안에 자석이 들어 있기 때문이고, 필통 뚜껑이 잘 닫히는 것도 자석 덕분입니다. 또 칠판에 종이를 붙일 때 쓰는 자석도 있습니다. 이렇게 자석은 작지만 우리에게 큰 도움을 줍니다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('F1_LIT_P1', 'frege', 4, '문학', '"너, 이노무 시키, 이리 안 와!"\n주인 영감의 고함 소리가 등 뒤에서 벼락같이 터졌다. 수남이는 자전거를 끌고 죽을힘을 다해 달렸다. 다리가 후들거리고 심장이 터질 것만 같았다.\n\'내가 왜 그랬을까? 아무리 화가 났어도 도둑질을 하는 게 아니었는데...\'\n수남이의 눈앞이 흐려졌다. 바람 때문에 눈물이 나는 건지, 무서워서 눈물이 나는 건지 알 수 없었다.\n오늘 낮에 있었던 일이다. 배달을 갔다가 바람이 불어 자전거가 넘어지는 바람에 고급 승용차에 흠집을 냈다. 차 주인은 수리비로 오천 원을 내오라며 자전거를 붙잡아 두었다. 수남이는 어쩔 줄 몰라 발만 동동 구르고 있는데, 구경하던 사람들이 소리쳤다.\n"얘, 도망가라! 그깟 흠집 가지고 무슨 오천 원이냐? 그냥 자전거 타고 도망가!"\n그 말에 홀린 듯 수남이는 자전거를 들고 튀었다. 하지만 지금 수남이의 가슴속은 쿵쾅거리는 소리로 가득 찼다.\n집에 돌아오니 아버지가 물끄러미 바라보셨다.\n"너, 얼굴이 왜 그 모양이냐?"\n수남이는 아무 말도 할 수 없었다. 아버지 앞에서 도둑질을 했다는 사실을 어떻게 말할 수 있을까? 수남이는 이불을 뒤집어쓰고 웅크렸다. 자전거 바퀴가 굴러가는 소리가 귓가에 맴도는 것 같았다.\n\n- 박완서, <자전거 도둑> 부분');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('F1_LIT_P3', 'frege', 5, '문학', '"이 바보."\n소녀가 조약돌을 집어 던졌다.\n소년은 저도 모르게 벌떡 일어섰다.\n단발머리를 나풀거리며 소녀가 막 달린다. 갈밭 사잇길로 들어섰다. 뒤에는 청량한 가을 햇살 아래 빛나는 갈꽃뿐.\n이제 저쯤 갈밭머리로 소녀가 나타나리라. 꽤 오랜 시간이 지났다고 생각됐다. 그런데도 소녀는 나타나지 않는다. 발돋움을 했다. 그러고도 상당한 시간이 지났다.\n저쪽 갈밭머리에 갈꽃이 한 옴큼 움직였다. 소녀가 갈꽃을 안고 있었다. 이제 천천히 걸어오고 있다. 유난히 맑은 가을 햇살이 소녀의 갈꽃 머리에서 반짝거렸다. 소녀 아닌 갈꽃이 들길을 걸어오는 것만 같았다.\n소년은 이 갈꽃이 아주 뵈지 않게 되기까지 그대로 서 있었다. 문득, 소녀가 던진 조약돌을 내려다보았다. 물기가 걷혀 있었다. 소년은 조약돌을 집어 주머니에 넣었다.\n\n다음 날부터 좀처럼 소녀는 보이지 않았다. 매일같이 개울가로 달려와 봐도 뵈지 않았다.\n학교에서는 쉬는 시간에 운동장을 살폈다. 남몰래 5학년 여자 반을 엿보기도 했다. 그러나 뵈지 않았다.\n그날도 소년은 주머니 속 조약돌을 만지작거리며 개울가로 나왔다.\n\n- 황순원, <소나기> 부분');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('F1_LIT_P5', 'frege', 6, '문학', '"옥희야."\n하고 불렀습니다. 나는\n"왜?"\n하고 대답하고 아저씨를 쳐다보았습니다.\n"너, 아범 보고 싶지 않니?"\n"아범?"\n나에게 아범이 있었던 것은 사실이나, 내가 세상에 나오기도 전에, 아범은 세상을 떠났다고 외할머니가 일러 주신 것이 생각났습니다.\n"응, 아범말이다. 네 아범은 참 훌륭한 사람이었단다. 나하구 아주 친한 친구였었단다."\n"아범은 어디 갔어?"\n"세상 떠났지."\n"세상 떠나면 못 와?"\n"못 오지."\n"왜?"\n"하늘나라로 갔으니까."\n나는 갑자기 서러워졌습니다. 아저씨도 아빠가 없는 것이 불쌍해 보였던지 나를 덥석 안아 올려 무릎 위에 앉히고, 머리를 쓰다듬어 주며 뺨에다 입을 맞추어 주었습니다. 그리고,\n"옥희는, 이제 누가 제일 좋으니?"\n하고 물었습니다. 나는,\n"어머니."\n하고 대답했습니다.\n"그 다음엔?"\n"그 다음엔, 아저씨."\n아저씨는 나를 꼭 껴안아 주었습니다. 그리고 내 뺨에다 입을 맞추었습니다.\n\n- 주요섭, <사랑손님과 어머니> 부분');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('F1_NON_P1', 'frege', 4, '비문학', '[지문]\n식물은 움직일 수 없지만, 스스로 양분을 만들고 자손을 퍼뜨리며 살아갑니다. 식물이 살아남기 위해 사용하는 놀라운 전략들에 대해 알아봅시다.\n\n가장 대표적인 생존 전략은 \'광합성\'입니다. 식물은 잎에 있는 엽록소를 이용해 햇빛을 흡수합니다. 그리고 뿌리에서 빨아들인 물과 잎의 기공으로 들이마신 이산화탄소를 재료로 하여 포도당이라는 양분을 만듭니다. 이 과정에서 우리에게 꼭 필요한 산소가 부산물로 나옵니다. 식물은 이렇게 만든 양분으로 줄기를 키우고 꽃을 피웁니다.\n\n식물의 또 다른 중요한 과제는 \'씨앗 퍼뜨리기\'입니다. 움직일 수 없는 식물은 자손을 멀리 보내기 위해 다양한 방법을 씁니다. 민들레나 단풍나무는 씨앗에 날개나 털을 달아 바람에 날려 보냅니다. 도꼬마리 같은 식물은 씨앗 끝을 갈고리 모양으로 만들어 동물 털이나 사람 옷에 붙어서 이동합니다.\n\n또한 맛있는 열매를 맺어 동물이 먹게 한 뒤, 배설물을 통해 씨앗이 멀리 퍼지게 하는 식물들도 있습니다. 벚나무나 참나무가 대표적입니다. 이처럼 식물은 움직이지 못하지만, 지혜로운 방법으로 생명을 이어가고 있습니다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('F1_NON_P3', 'frege', 5, '비문학', '[지문]\n오늘날 우리는 인터넷과 스마트폰을 통해 수많은 사람과 소통하며 살아갑니다. 하지만 얼굴이 보이지 않는다는 점을 악용하여 남에게 상처를 주는 일이 빈번하게 발생하고 있습니다. 악성 댓글이나 근거 없는 소문 유포가 대표적인 예입니다. 이러한 사이버 폭력은 피해자에게 씻을 수 없는 고통을 줍니다.\n따라서 우리는 올바른 디지털 예절, 즉 \'네티켓\'을 지켜야 합니다. 첫째, 상대방을 존중하는 마음을 가져야 합니다. 화면 너머에 나와 똑같은 감정을 가진 사람이 있다는 사실을 기억해야 합니다. 내가 듣기 싫은 말은 남에게도 하지 말아야 합니다.\n둘째, 정확하지 않은 정보를 함부로 퍼뜨리지 말아야 합니다. 사실 확인이 되지 않은 소문을 공유하는 것은 큰 혼란을 일으킬 수 있습니다. 정보를 공유하기 전에 그것이 믿을 만한지, 누군가에게 피해를 주지는 않는지 신중하게 생각해야 합니다.\n셋째, 개인 정보를 소중히 다루어야 합니다. 자신의 정보뿐만 아니라 타인의 정보도 함부로 유출해서는 안 됩니다.\n디지털 세상은 우리가 함께 만들어가는 공간입니다. 서로 배려하고 존중하는 태도를 가질 때, 비로소 건강하고 행복한 디지털 세상을 만들 수 있을 것입니다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('F1_NON_P5', 'frege', 6, '비문학', '[지문]\n세종 대왕이 훈민정음을 창제한 것은 백성을 사랑하는 마음, 즉 \'애민 정신\'에서 비롯되었습니다. 당시에는 한자를 사용했는데, 한자는 배우기가 매우 어려워 일반 백성들은 자신의 생각을 글로 표현하기 힘들었습니다. 세종 대왕은 이러한 백성들의 고충을 안타깝게 여겨 누구나 쉽게 배우고 쓸 수 있는 우리 글자를 만들기로 결심했습니다.\n\n훈민정음은 매우 과학적인 원리로 만들어졌습니다.\n첫째, \'상형의 원리\'입니다. 자음은 발음 기관의 모양을 본떠 만들었고, 모음은 하늘(·), 땅(ㅡ), 사람(ㅣ)의 모양을 본떠 만들었습니다. 예를 들어 \'ㄱ\'은 혀뿌리가 목구멍을 막는 모양을, \'ㄴ\'은 혀가 윗잇몸에 닿는 모양을 본뜬 것입니다.\n둘째, \'가획의 원리\'입니다. 기본 글자에 획을 더하여 소리의 세기를 나타냈습니다. \'ㄱ\'에 획을 더하면 \'ㅋ\'이 되고, \'ㄴ\'에 획을 더하면 \'ㄷ\', \'ㅌ\'이 되는 식입니다.\n\n이처럼 훈민정음은 창제 동기가 숭고할 뿐만 아니라, 그 제자 원리가 매우 독창적이고 과학적이어서 세계적으로 그 우수성을 인정받고 있습니다. 유네스코에서는 \'세종대왕 문해상\'을 제정하여 문맹 퇴치에 기여한 사람들에게 상을 주고 있습니다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('R1_LIT_P1', 'russell', 7, '문학', '(가)\n나 보기가 역겨워\n가실 때에는\n말없이 고이 보내 드리우리다.\n\n영변(寧邊)에 약산(藥山)\n진달래꽃\n아름 따다 가실 길에 뿌리우리다.\n\n가시는 걸음 걸음\n놓인 그 꽃을\n사뿐히 즈려 밟고 가시옵소서.\n\n나 보기가 역겨워\n가실 때에는\n죽어도 아니 눈물 흘리우리다.\n\n- 김소월, <진달래꽃>\n\n(나)\n"이걸 보면 벌써 도둑은 저 건너 산을 넘었을 게다."\n하고 응칠이는 얼른 논둑에서 몽둥이를 집어 들었다. 그리고 벼를 훔쳐 간 놈의 발자국을 찾으려고 논바닥을 살폈다. 그러나 논바닥에는 아무런 흔적도 없었다.\n참 이상한 일이었다. 벼를 베어 간 흔적은 있는데 도둑이 들어온 발자국도, 나간 발자국도 없는 것이다.\n\'이건 분명히 하늘에서 떨어진 도둑이 아니고는 못 할 짓인데…….\'\n응칠이는 귀신에 홀린 듯하여 멍하니 서 있었다. 바로 이때였다.\n"악!"\n하는 비명 소리가 벼 포기 속에서 났다. 깜짝 놀라 그곳을 보니 검은 그림자가 벼 포기 속에서 꿈틀거리고 있었다. 응칠이는 달려들어 몽둥이로 그놈의 등을 후려갈겼다.\n"악!"\n하고 다시 비명을 지르며 그놈은 푹 고꾸라졌다. 응칠이는 놈의 허리를 잡고 일으켜 세웠다. 그리고 복면을 벗겨 보았다.\n"아니, 이게 웬일이냐?"\n응칠이는 눈을 의심했다. 복면을 벗은 그 얼굴은 바로 자기의 아우 응오가 아닌가!\n"네가, 네가 벼를 훔쳤단 말이냐?"\n응오의 얼굴은 흙투성이가 되어 있었다. 응칠이는 기가 막혀 입이 다물어지지 않았다.\n"형님!"\n하고 부르며 응오는 형의 가슴에 얼굴을 묻고 흐느껴 울었다.\n"왜, 왜 네 벼를 네가 훔쳐야 한단 말이냐?"\n응오의 입에서 나오는 말은 형의 가슴을 더욱 아프게 했다.\n"벼를 베어 봤자 남는 게 있어야지요. 지주에게 뺏기고, 빚 갚고 나면 빈털터린데, 차라리 도둑맞았다고 소문을 내고 제가 먹는 게 낫지요."\n응칠이는 몽둥이를 던져 버렸다. 그리고 아우의 손을 잡고 일으켰다.\n"가자, 집으로 가자."\n"형님, 저는 못 갑니다. 이 벼를 다 베어 가지고 가야 합니다."\n"그만두어라. 도둑질까지 해 가면서 농사를 지으면 뭘 하니. 다 집어치우고 나하고 같이 떠나자."\n응칠이는 아우의 등을 밀었다. 그러나 응오는 버티고 서서 움직이지 않았다.\n"형님, 저는 못 떠납니다. 아내와 늙으신 어머니를 두고 어디로 간단 말입니까?"\n응칠이는 더 이상 할 말이 없었다. 그는 하늘을 쳐다보며 긴 한숨을 내쉬었다. 달빛만이 차갑게 그들을 비추고 있었다.\n\n- 김유정, <만무방>');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('R1_LIT_P3', 'russell', 8, '문학', '(가)\n넓은 벌 동쪽 끝으로\n옛이야기 지줄대는 실개천이 휘돌아 나가고,\n얼룩백이 황소가\n해설피 금빛 게으른 울음을 우는 곳,\n― 그곳이 차마 꿈엔들 잊힐 리야.\n\n질화로에 재가 식어지면\n비인 밭에 밤바람 소리 말을 달리고,\n엷은 졸음에 겨운 늙으신 아버지가\n짚베개를 돋아 고이시는 곳,\n― 그곳이 차마 꿈엔들 잊힐 리야.\n\n흙에서 자란 내 마음\n파아란 하늘빛이 그리워\n함부로 쏜 화살을 찾으러\n풀섶 이슬에 함추름 휘적시던 곳,\n― 그곳이 차마 꿈엔들 잊힐 리야.\n\n전설(傳說) 바다에 춤추는 밤물결 같은\n검은 귀밑머리 날리는 어린 누이와\n아무렇지도 않고 예쁠 것도 없는\n사철 발 벗은 아내가\n따가운 햇살을 등에 지고 이삭 줍던 곳,\n― 그곳이 차마 꿈엔들 잊힐 리야.\n\n하늘에는 성근 별\n알 수도 없는 모래성으로 발을 옮기고,\n서리 까마귀 우지짖고 지나가는 초라한 지붕,\n흐릿한 불빛에 돌아앉아 도란도란거리는 곳,\n― 그곳이 차마 꿈엔들 잊힐 리야.\n\n- 정지용, <향수(鄕愁)>\n\n(나)\n"닥터 리, 위대하오. 내 수술 솜씨는 제1전선 야전 병원에서 본 이후 처음이오."\n스텐코프는 엄지손가락을 쑥 내밀며 감탄에 마지않았다.\n이인국 박사는 스텐코프의 혹을 떼어 낸 수술을 성공적으로 마쳤던 것이다.\n(중략)\n이인국 박사는 회심의 미소를 지었다. 이제 소련군 점령 하에서도 살아남을 길이 열린 것이다. 그는 일제 시대에는 철저한 친일파로, 그리고 이제는 친소파로 변신에 성공했다.\n\n1·4 후퇴 때 남쪽으로 내려온 이인국 박사는 다시 새로운 길을 찾았다. 미군정이 시작되자 그는 능숙한 영어 실력을 발휘하여 미군 장교들과 친분을 쌓았다.\n"헬로, 캡틴 리. 닥터 리는 진정한 애국자요. 우리의 친구입니다."\n브라운 대사는 이인국 박사를 치켜세웠다. 이인국 박사는 브라운에게 고려청자를 선물하며 미국에 갈 수 있도록 주선해 줄 것을 부탁했다.\n"땡큐, 땡큐. 미국 국무성 초청 케이스로 갈 수 있도록 힘써 보리다."\n브라운의 확답을 듣자 이인국 박사는 안도의 숨을 내쉬었다. 딸 나미가 미국인 교수와 결혼하겠다고 했을 때 잠시 갈등했으나, 그는 곧 생각을 고쳐먹었다.\n\'흥, 이왕이면 든든한 빽이 있는 게 낫지. 미국 사위, 나쁠 것 없잖아.\'\n그는 창밖을 내다보며 중얼거렸다.\n"나보다 더 날뛰던 놈들도 있는데, 나쯤이야... 흥, 식민지 백성이 별수 있었어? 주는 떡을 안 먹는 놈이 바보지. 다 그놈이 그놈이었어."\n이인국 박사의 얼굴에는 시대의 격랑을 교묘하게 헤쳐 온 자만의 안도감과 비릿한 웃음이 서려 있었다.\n\n- 전광용, <꺼삐딴 리>');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('R1_LIT_P5', 'russell', 9, '문학', '(가)\n동짓(冬至)달 기나긴 밤을 한 허리를 버혀 내여\n춘풍(春風) 니불 아레 서리서리 너헛다가\n어론 님 오신 날 밤이여든 구뷔구뷔 펴리라\n\n- 황진이\n\n(나)\n창(窓) 내고쟈 창을 내고쟈 이 내 가슴에 창 내고쟈\n고모장지 셰살장지 들장지 열장지 암돌져귀 수돌져귀 배목걸새 크나큰 장도리로 뚝딱 박아 이 내 가슴에 창 내고쟈\n잇다감 하 답답할 제면 여다져 볼가 하노라\n\n- 작자 미상\n\n(다)\n용왕이 대경(大驚)하야,\n"네 이놈 토끼야! 네가 이리 미련하단 말이냐? 사람이나 짐승이나 뱃속에 간이 들었거늘, 어찌 네놈은 간이 출입한단 말이냐? 네 말이 당토치 않은지라, 당장 네 배를 갈라 간을 보리라."\n하고 도부수(刀斧手)를 호령하니, 토끼란 놈이 긍경이나 할 놈이냐. 토끼 뱃속에 무엇이 꽉 찼는지 모르되, 제 꾀를 믿고 눈 하나 깜짝 아니 하고 썩 나서며,\n"아서라 왕(王)이야, 내 간 산 곳을 들어라. 간이라 하는 것은 보화(寶貨)라. 뱃속에 넣고 다니면 더운 뱃속에 썩기도 쉽고, 남의 눈에 띄면 끄집어 가기도 하는 고로 의구한 신선들이 바둑 두는 바위 아래 샘물 속에 깨끗이 씻어 심청 반석 위에 고이 얹어 두고 왔나니라."\n(중략)\n"왕은 그리 아오. 간을 내어다가 씻어서 방석 위에 널어 두고, 소신(小臣)의 배는 텅 비었으니 무엇을 가지고 와 약에 쓰려 하시오? 만약에 소신의 배를 갈라 보아 간이 있으면 좋거니와, 만일에 간이 없으면 불쌍하고 무죄한 소신만 죽을 뿐 아니라, 왕의 병도 차도가 없으리니 이 일을 어찌 하오리까?"\n용왕이 듣고 보니 그럴듯한지라, 토끼를 짐짓 다시 달래어 말하기를,\n"그러면 네가 육지로 나가서 간을 가지고 오겠느냐?"\n토끼가 대답하되,\n"소신이 비록 간은 육지에 두고 왔으나 목숨은 여기 있사오니, 왕의 병환이 나으실진대 어찌 간을 아끼오리까."\n하니 용왕이 크게 기뻐하여 잔치를 베풀고 토끼를 육지로 보내 주기로 하였더라.\n\n- 작자 미상, <수궁가(水宮歌)>');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('R1_NON_P1', 'russell', 7, '비문학', '시장에서 물건의 가격은 어떻게 결정될까? 이것은 \'수요\'와 \'공급\'의 상호작용으로 설명할 수 있다. \'수요\'란 소비자가 어떤 가격에 재화나 서비스를 구매하고자 하는 욕구를 말하고, \'공급\'은 생산자가 어떤 가격에 판매하고자 하는 욕구를 말한다.\n일반적으로 수요는 가격이 오르면 감소하고 가격이 내리면 증가한다. 이를 \'수요의 법칙\'이라고 한다. 반대로 공급은 가격이 오르면 이윤을 더 많이 남길 수 있으므로 증가하고, 가격이 내리면 감소한다. 이를 \'공급의 법칙\'이라고 한다. 시장에서는 사려는 사람(수요자)과 팔려는 사람(공급자)이 만나 거래가 이루어지는데, 수요량과 공급량이 일치하는 지점에서 가격이 결정된다. 이를 \'균형 가격\'이라고 한다.\n\n한편, 가격이 변할 때 수요량이나 공급량이 얼마나 민감하게 변하는지를 나타내는 개념이 있다. 바로 \'가격 탄력성\'이다. 가격 변화율에 비해 수요량 변화율이 더 크면 \'탄력적\'이라고 하고, 작으면 \'비탄력적\'이라고 한다.\n예를 들어, 쌀이나 소금 같은 생필품은 가격이 올라도 살 수밖에 없고, 가격이 내려도 많이 사둘 필요가 없으므로 수요량이 크게 변하지 않는다. 즉, 가격 탄력성이 비탄력적이다. 반면 보석이나 명품 가방 같은 사치품은 가격이 오르면 구매를 쉽게 포기하고, 가격이 내리면 수요가 급격히 늘어날 수 있다. 즉, 가격 탄력성이 탄력적이다.\n\n기업은 상품의 가격 탄력성을 고려하여 가격 정책을 세운다. 탄력적인 상품은 가격을 낮춰서 많이 파는 \'박리다매\' 전략이 유리하고, 비탄력적인 상품은 가격을 올려도 수요가 크게 줄지 않으므로 고가 전략을 쓰기도 한다. 이처럼 수요와 공급, 그리고 탄력성의 개념을 이해하면 우리 주변의 가격 변화를 더 잘 이해할 수 있다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('R1_NON_P3', 'russell', 8, '비문학', '우리가 살아가는 데 필요한 다양한 권리 중 재산권은 크게 \'물권(物權)\'과 \'채권(債權)\'으로 나뉜다.\n\'물권\'은 문자 그대로 특정한 물건을 직접 지배하여 이익을 얻을 수 있는 배타적인 권리다. 대표적인 예로 소유권이 있다. 내 소유인 자전거는 누구의 간섭도 받지 않고 내가 마음대로 사용하거나 처분할 수 있고, 누구에게나 "이건 내 거야"라고 주장할 수 있다. 이처럼 물권은 세상 모든 사람에게 자신의 권리를 주장할 수 있어 \'절 대권\'이라고도 불린다.\n반면 \'채권\'은 특정한 사람(채권자)이 다른 특정한 사람(채무자)에게 일정한 행위(급부)를 요구할 수 있는 권리다. 친구에게 돈을 빌려줬다면 나는 친구에게 돈을 갚으라고 요구할 수 있는 채권을 가진다. 하지만 이 권리는 오직 돈을 빌려 간 친구에게만 행사할 수 있지, 다른 친구에게 대신 갚으라고 요구할 수는 없다. 이처럼 채권은 특정한 상대방에게만 주장할 수 있어 \'상대권\'이라고 한다.\n\n물권과 채권이 충돌하면 원칙적으로 물권이 우선한다. 이를 \'물권 우선주의\'라고 한다. 예를 들어, 내가 전세를 살고 있는 집(임차권=채권)을 집주인이 다른 사람에게 팔아버리면, 새로운 집주인(소유권=물권)에게는 임차권을 주장하기 어려울 수 있다. 그래서 법은 등기와 같은 제도를 통해 채권을 물권처럼 보호받을 수 있는 장치를 마련해 두기도 한다.\n\n또한 채권자에게는 자신의 채권을 지키기 위해 채무자의 권리를 대신 행사할 수 있는 \'채권자 대위권\' 같은 특수한 권리도 주어진다. 이는 채무자가 빚을 갚을 능력이 있는데도 자신의 권리를 행사하지 않아 채권자가 돈을 돌려받지 못할 위험이 있을 때, 채권자가 채무자를 대신하여 그 권리를 행사하는 것이다. 이처럼 법은 다양한 권리 관계의 균형을 맞추기 위해 정교하게 설계되어 있다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('R1_NON_P5', 'russell', 9, '비문학', '우리가 어떤 새로운 사실을 알게 되거나 주장을 펼칠 때, 논리적인 근거를 들어 설명하는 과정을 \'추론\'이라고 한다. 대표적인 추론 방식으로는 \'연역법\'과 \'귀납법\'이 있다.\n\n\'연역법\'은 이미 알고 있는 일반적인 원리나 법칙(대전제)을 바탕으로 구체적인 사실(소전제)을 대입하여 새로운 결론을 이끌어내는 방식이다. 가장 유명한 예는 다음과 같다.\n대전제: 모든 사람은 죽는다.\n소전제: 소크라테스는 사람이다.\n결론: 그러므로 소크라테스는 죽는다.\n연역법의 가장 큰 특징은 전제가 참이라면 결론도 반드시 참이라는 \'필연성\'을 가진다는 것이다. 하지만 대전제 자체가 잘못되었다면 결론도 틀릴 수 있으며, 이미 전제 속에 포함된 내용을 확인하는 것이어서 새로운 지식을 확장하는 데에는 한계가 있다.\n\n반면 \'귀납법\'은 여러 가지 구체적인 사실이나 경험을 관찰하여 그 속에 담긴 공통적인 법칙을 찾아내어 일반적인 결론을 도출하는 방식이다.\n관찰 1: 어제 뜬 해는 서쪽으로 졌다.\n관찰 2: 오늘 뜬 해도 서쪽으로 졌다.\n...\n결론: 그러므로 모든 해는 서쪽으로 질 것이다.\n귀납법은 우리의 지식을 넓히는 데 유용하지만, 결론이 참일 개연성(가능성)이 높을 뿐 \'필연적\'으로 참은 아니라는 한계가 있다. 단 하나의 반례(예외)만 나타나도 결론이 거짓이 될 수 있기 때문이다. 예를 들어, 오랫동안 모든 백조는 희다고 믿었지만 검은 백조(블랙 스완)가 발견되면서 그 결론이 깨진 것이 대표적이다.\n\n이처럼 연역법과 귀납법은 서로 다른 방향으로 사고를 전개하지만, 상호 보완적으로 작용하며 인류의 지식을 발전시켜 왔다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('W1_LIT_P1', 'wittgenstein', 10, '문학', '(가)\n아무 소리도 없이 말도 없이\n등 뒤로 털썩\n밧줄이 날아와 나는\n뛰어가 밧줄을 잡아다 배를 맨다\n아주 천천히 그리고 조용히\n배는 멀리서부터 닿는다\n\n사랑은,\n호젓한 부둣가에 우연히,\n별 그럴 일도 없으면서 넋 놓고 앉았다가\n배가 들어와\n던져지는 밧줄을 받는 것\n그래서 어찌할 수 없이\n배를 매게 되는 것\n\n잔잔한 바닷물 위에\n구름과 빛과 시간과 함께\n떠 있는 배\n\n배를 매면 구름과 빛과 시간이 함께\n매어진다는 것도 처음 알았다\n사랑이란 그런 것을 처음 아는 것\n\n빛 가운데 배는 울렁이며\n온종일을 떠 있다\n\n- 장석남, <배를 매며>\n\n(나)\n"그럼, 아까 그 늙은 중이……."\n"그가 바로 네 아비다."\n옥화는 갑자기 무엇을 생각한 듯이, 성기의 귓바퀴를 들추어 보았다. 거기에는 으레 있을 점이 하나 또렷하게 박혀 있었다.\n"네가 이번 여름에 장에 갔다가, 웬 낯선 영감을 만나지 않더냐? 왼손잡이더냐, 오른손잡이더냐?"\n"왼손잡이입디다."\n"그래, 몸집이 작고, 얼굴에 사마귀가 없더냐?"\n"얼굴은 자세히 못 보았지만, 몸집은 작아 보입디다."\n"음, 그가 외할아버지시다."\n성기는 고개를 들어 어머니의 얼굴을 쳐다보았다. 옥화는 마치 꿈꾸는 사람처럼 나직이 중얼거렸다.\n"네 이모(계연)의 왼쪽 귓바퀴 위에도, 너와 똑같은 점이 있더구나."\n성기는 그제야 모든 것을 깨달은 듯, 고개를 떨구었다. 그것은 너무나 엄청난 사실이었다. 옥화는 다시 성기의 손을 잡으며 말했다.\n"성기야, 이것은 다 하늘이 정한 운명이다. 누구를 원망하겠느냐. 계연이는 네 이모다. 그러니 이제 그만 단념해라."\n(중략)\n이튿날 아침, 성기는 춘천을 향해 떠나는 계연과 체장수 영감을 배웅하고 돌아왔다. 성기는 한동안 알 수 없는 병으로 자리에 눕게 되었다. 옥화는 성기가 죽을지도 모른다는 생각에, 굿도 하고 용하다는 의원도 불러 보았지만 차도가 없었다. 그러던 어느 날, 옥화는 성기에게 물었다.\n"성기야, 너 소원이 뭐냐? 네가 하고 싶은 대로 다 해 줄 테니 말해 보아라."\n성기는 힘없는 목소리로 대답했다.\n"어머니, 엿판 하나만 맞춰 주세요."\n옥화는 깜짝 놀랐지만, 곧 아들의 뜻을 알아차리고 엿판을 맞춰 주었다.\n성기가 병석에서 일어난 것은 그로부터 며칠 뒤였다. 성기는 옥화가 맞춰 준 새하얀 엿판을 걸머지고 대문 밖을 나섰다. \n"성기야, 어디로 가려느냐?"\n옥화의 물음에 성기는 잠시 생각에 잠겼다. 하동 쪽으로 가면 계연을 만날 수도 있었다. 그러나 성기는 하동과는 반대 방향인 구례 쪽을 향해 발걸음을 옮겼다. 그의 콧노래는 어느새 육자배기 가락으로 변해 있었다. 벚꽃이 눈처럼 흩날리는 길 위로, 성기의 뒷모습이 점점 멀어져 갔다.\n\n- 김동리, <역마>');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('W1_LIT_P3', 'wittgenstein', 11, '문학', '(가)\n살어리 살어리랏다 쳥산(靑山)애 살어리랏다.\n멀위랑 ᄃᆞ래랑 먹고 쳥산(靑山)애 살어리랏다.\n얄리얄리 얄라셩 얄라리 얄라.\n\n우러라 우러라 새여 자고 니러 우러라 새여.\n널라와 시름 한 나도 자고 니러 우니노라.\n얄리얄리 얄라셩 얄라리 얄라.\n\n어듸라 더디던 돌코 누리라 마치던 돌코.\n믜리도 괴리도 업시 마자셔 우니노라.\n얄리얄리 얄라셩 얄라리 얄라.\n\n살어리 살어리랏다 바ᄅᆞ래 살어리랏다.\nᄂᆞᄆᆞ자기 구조개랑 먹고 바ᄅᆞ래 살어리랏다.\n얄리얄리 얄라셩 얄라리 얄라.\n\n가다니 배브른 도긔 설진 강수를 비조라.\n조롱곳 누로기 매와 잡사와니 내 엇디 ᄒᆞ리잇고.\n얄리얄리 얄라셩 얄라리 얄라.\n\n- 작자 미상, <청산별곡>\n\n(나)\n운영이 붓을 들어 김 진사에게 답서를 쓰니 다음과 같았다.\n"박명한 첩 운영은 재배하고 낭군께 사뢰나이다. 삼가 생각건대, 궁궐 담장은 높고 깊은데 규방은 닫혀 있어, 편지를 전할 인편은 끊어지고 그리움만 해를 거듭하였습니다. \n(중략)\n낭군께서는 첩의 재주 없음을 생각지 않으시고, 첩이 지은 시의 보잘것없는 재주를 사랑하시어 잠 못 이루는 병을 앓기에 이르셨습니까? 이 몸은 비록 깊은 궁궐에 갇혀 있고 질곡에 매여 있는 몸이지만, 낭군을 사모하는 마음이야 어찌 금석(金石)보다 굳지 않겠습니까?\n하오나 대군께서 내리신 엄명은 서릿발 같고, 궁중의 법도는 지극히 엄합니다. 또한 제 곁에는 시기하고 질투하는 자들이 많아 눈과 귀가 곳곳에 도사리고 있습니다. 만약 이 일이 누설된다면 제 목숨이 보존되기 어려움은 말할 것도 없고, 낭군께도 큰 화가 미칠 것이니 두려운 마음 금할 길이 없습니다.\n바라옵건대 낭군께서는 마음을 굳게 잡수시고 병을 떨치고 일어나, 학업에 정진하여 과거에 급제하시고 가문을 빛내시옵소서. 이승에서 못다 한 인연은 후생을 기약하고자 하오니, 부디 옥체를 ⓐ보전하시어 만수무강하소서."\n운영은 편지를 다 쓰고 나자 흐르는 눈물을 걷잡을 수 없었다. 달빛은 더욱 희미해지고, 멀리서 들려오는 기러기 울음소리가 애간장을 녹이는 듯하였다.\n\n- 작자 미상, <운영전>');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('W1_LIT_P5', 'wittgenstein', 12, '문학', '(가)\n나뭇잎은 햇빛에 싱싱하게 윤이 나고\n그와 비슷한 촌수로 물결은 더욱 빛나는 무늬를 끊임없이 빚고\n또한 바람은 연방 그리운 것 위에 볼 줄밖에 모르는 이것들.\n천날 만날 한결같은 오, 이것들을 보아라,\n물방울처럼 스러졌다가 이어져 마음은 움직이는 것을 통하여\n사랑의 연습만을 부지런히 하고\n그것을 영원토록 지치지 않고 하겠다는 그것 말고 나는 볼 수가 없구나.\n참으로 환장할 일은 이것이로다.\n\n- 박재삼, <그리움>\n\n(나)\n"아비는 어쩔 셈으로 송화 누이의 눈을 멀게 했는가."\n사내의 말은 이제 그것을 묻고 있었다.\n"아직도 나를 원망하고 있느냐?"\n노인은 그러나 사내의 말은 들이지 않고 자신의 말만을 뇌까리고 있었다.\n"원망이라니요? 다 지난 일을. 제가 묻고 싶은 것은……."\n"그렇다, 용서해라. 너는 내 자식이 아니었으니 나를 버리고 나간 것은 나무랄 일이 아니었다. 하나 송화는 그럴 수가 없었다. 제 어미가 없으니 내가 곁을 지켜 줘야 했다. 하지만 나도 이제는 너무 늙고 지쳤어. 내가 죽고 나면 송화는 누구를 의지해 살아가겠느냐. 눈을 잃어버리면…… 그러면 송화는 좋든 싫든 내 곁에 남을 수밖에 없지 않겠느냐. 몸이 성한 너까지 나를 버리고 떠나갔는데, 눈먼 누이가 내 곁을 떠나 어디로 가겠느냐. 내 욕심이었다. 너희와 끝까지 함께 있고 싶었던 내 욕심이……."\n노인의 목소리는 흐느낌에 섞여 끊어질 듯 이어지고 있었다.\n"하지만 그 때문만은 아니었다. 너도 알다시피 송화의 소리에는 결정적인 한(恨)이 부족했다. 소리는 맑고 고왔지만 마음 깊은 곳에서 우러나오는 그 무엇이 없었어. 그것을 채워 주고 싶었다. 사람의 한이라는 것은 일생을 살아가면서 이 가슴 저 가슴에 첩첩이 쌓여 맺히는 것인데, 송화는 아직 어려서 그런 한을 알 지 못했어. 어미를 일찍 여의었지만 내 그늘 시 하도 컸던 탓인지도 모를 일이지. 그래서 내가 나섰던 게다. 내 자식의 눈을 멀게 해서라도 그 가슴에 한을 심어 주고 싶었단 말이다. 소리의 완성을 위해서……."\n동호는 숨이 막힐 것 같았다. 소리의 완성, 그것이 무엇이기에 자식의 눈까지 멀게 했단 말인가.\n(중략)\n다음 날 아침, 사내는 다시 길을 떠났다. 잠에서 깨어난 여인은 사내가 떠난 길을 멍하니 바라보며 소리 한 대목을 흥얼거리고 있었다. 그것은 지난밤 사내와 함께 맞추었던 바로 그 춘향가의 이별 대목이었다. 여인의 소리는 맑고 애절했다. 그리고 그 소리에는 이제껏 보지 못했던 깊은 한이 서려 있었다.\n\n- 이청준, <서편제>');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('W1_NON_P1', 'wittgenstein', 10, '비문학', '시장 경제에서 자원은 가격 기구를 통해 효율적으로 배분된다. 이때 시장 참여자들이 얻는 이득은 \'잉여(Surplus)\'라는 개념으로 설명할 수 있다. \n\'소비자 잉여\'란 소비자가 어떤 재화를 구매하기 위해 지불할 용의가 있는 최대 금액에서 실제로 지불한 가격을 뺀 차액을 말한다. 예를 들어, 어떤 소비자가 사과 한 개에 2,000원까지 낼 의향이 있었는데 실제 가격이 1,000원이라면, 그는 1,000원만큼의 소비자 잉여를 얻게 된다. 이는 그래프상에서 수요 곡선 아래이면서 시장 가격선 위의 면적으로 표시된다.\n반대로 \'생산자 잉여\'는 생산자가 재화를 판매하여 얻은 실제 수입에서 그 재화를 공급하기 위해 받아야만 했던 최소한의 금액(비용)을 뺀 차액이다. 이는 그래프상에서 시장 가격선 아래이면서 공급 곡선 위의 면적에 해당한다. 소비자 잉여와 생산자 잉여의 합을 \'사회적 총잉여\'라 하며, 완전 경쟁 시장의 균형 상태에서 이 사회적 총잉여는 극대화된다.\n\n그러나 정부는 형평성이나 사회적 안정을 위해 시장 가격에 개입하기도 하는데, 대표적인 것이 \'가격 규제\'이다. 그중 \'최고 가격제(Price Ceiling)\'는 물가 안정이나 소비자 보호를 위해 가격이 일정 수준 이상 오르지 못하도록 상한선을 두는 제도이다. 아파트 분양가 상한제나 이자율 제한 등이 이에 해당한다. 최고 가격이 시장 균형 가격보다 낮게 설정되면, 수요량은 늘어나고 공급량은 줄어들어 \'초과 수요\'가 발생한다. 이 경우 소비자 잉여는 증가할 수도 있지만(낮은 가격 혜택), 생산자 잉여는 감소하고 거래량이 줄어들어 결과적으로 사회적 총잉여의 감소, 즉 \'자중 손실(Deadweight Loss)\'이 발생한다. 또한 상품을 구하지 못한 소비자들이 웃돈을 주고 거래하는 암시장이 형성되거나 상품의 품질이 저하되는 부작용이 나타나기도 한다.\n\n이와 반대인 \'최저 가격제(Price Floor)\'는 공급자를 보호하기 위해 가격의 하한선을 설정하는 제도로, 최저 임금제가 대표적이다. 이 역시 시장 균형 가격보다 높게 설정될 때 효과가 있으며, 초과 공급(비자발적 실업 등)을 유발하고 자중 손실을 초래할 수 있다. 경제학에서는 이를 통해 정부의 개입이 의도와 달리 비효율성을 낳을 수 있음을 지적한다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('W1_NON_P3', 'wittgenstein', 11, '비문학', '언어 철학의 핵심 과제 중 하나는 언어 표현이 외부 세계의 대상을 어떻게 가리키는지, 즉 \'지시(Reference)\'의 문제를 해명하는 것이다. 이 문제에 대해 현대 분석 철학의 기초를 닦은 프레게와 러셀은 서로 다른 해법을 제시했다.\n\n프레게는 1892년 논문 <뜻과 지시체에 관하여>에서 언어 표현의 의미를 \'뜻(Sinn, Sense)\'과 \'지시체(Bedeutung, Reference)\'로 엄격히 구분했다. 그에 따르면 \'지시체\'는 단어가 가리키는 실제 대상이고, \'뜻\'은 그 지시체가 제시되는 방식이다. 예를 들어 \'샛별\'과 \'개밥바라기\'는 모두 금성이라는 동일한 \'지시체\'를 갖지만, 각각 \'아침에 뜨는 별\'과 \'저녁에 뜨는 별\'이라는 서로 다른 \'뜻\'을 지닌다. 프레게는 이러한 구분을 통해 "a=b"와 같은 동일성 진술이 어떻게 정보적 가치를 지닐 수 있는지 설명했다. 하지만 그의 이론은 "현 프랑스 국왕"처럼 현실에 존재하지 않는 대상을 가리키는 \'빈 지시어\'가 포함된 문장의 진리치를 설명하는 데 어려움이 있었다. 프레게는 이러한 문장은 뜻은 있지만 지시체(진리치)가 결여되어 있어 참도 거짓도 아니라고 보았다.\n\n반면 러셀은 프레게의 이원론적 의미론을 비판하며, \'한정 기술구(Definite Description)\'에 대한 분석을 통해 문제 해결을 시도했다. 그는 "현 프랑스 국왕은 대머리이다"와 같은 문장을 논리적으로 분석하면 세 가지 명제, 즉 \'현 프랑스 국왕이 적어도 한 명 존재한다\', \'현 프랑스 국왕은 오직 한 명이다\', \'그는 대머리이다\'의 연언(AND 결합)으로 환원된다고 주장했다. 따라서 현실 세계에 \'현 프랑스 국왕\'이 존재하지 않는다면 첫 번째 명제가 거짓이 되므로, 전체 문장은 무의미한 것이 아니라 \'거짓\'인 명제가 된다. 러셀은 고유명사처럼 보이는 많은 표현들이 사실은 위장된 한정 기술구이며, 그것을 논리적 구조로 풀어서 분석함으로써 존재하지 않는 대상에 대한 언급이 야기하는 혼란을 해소할 수 있다고 보았다. 그의 \'기술 이론\'은 언어의 표면적 문법 구조와 심층적 논리 구조가 다를 수 있음을 보여주었다.');
INSERT INTO diag_passages (id, tier, level, genre, text_md) VALUES ('W1_NON_P5', 'wittgenstein', 12, '비문학', '일반적으로 우리 몸의 면역 체계에서 \'킬러 T세포(세포독성 T림프구)\'는 바이러스에 감염된 세포나 암세포 표면의 특정 항원을 T세포 수용체(TCR)로 정확히 인식하여 제거한다고 알려져 있다. 그러나 최근 연구들은 특정 항원을 인지하지 않고도 주변 환경의 신호만으로 활성화되는 이른바 \'방관자(Bystander) 킬러 T세포\'의 존재와 역할에 주목하고 있다.\n\n방관자 킬러 T세포는 직접적으로 항원을 만나지 않아도, 감염 부위 주변에서 분비되는 인터루킨(IL-12, IL-15, IL-18 등)과 같은 염증성 사이토카인에 의해 활성화된다. 이렇게 깨어난 세포들은 항원 특이성과 무관하게 퍼포린이나 그랜자임 같은 독성 물질을 분비하거나, 면역 조절 물질인 인터페론 감마를 방출하여 주변 세포들에게 영향을 미친다.\n\n이러한 방관자 활성화 기제는 양날의 검과 같다. 긍정적인 측면에서는 초기 감염 시 특정 항원 특이 T세포가 충분히 증식하기 전에 신속하게 바이러스 증식을 억제하거나, 항원을 숨기고 도망가는(항원 회피) 바이러스나 암세포까지 공격하여 방어막을 형성할 수 있다. 이는 인체의 면역 방어 효율을 높이는 중요한 전략이 된다.\n\n하지만 부정적인 측면도 무시할 수 없다. 방관자 킬러 T세포는 적과 아군을 구별하는 항원 인식 과정이 생략되어 있기 때문에, 때로는 감염되지 않은 정상 조직까지 무차별적으로 공격하여 과도한 염증 반응이나 조직 손상을 유발할 수 있다. A형 간염 바이러스 감염 시 발생하는 심각한 간 손상이나, 류마티스 관절염, 다발성 경화증과 같은 자가면역 질환의 발병 및 악화 과정에 이들 방관자 T세포가 깊이 관여한다는 사실이 속속 밝혀지고 있다. 따라서 이들의 활성, 특히 \'NKG2D\'와 같은 수용체를 통한 작용 기제를 정밀하게 제어하는 기술은 자가면역 질환의 새로운 치료법 개발에 핵심적인 열쇠가 될 것이다.');
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_Q01', 'S1_LIT_P1', 'sohssure', '지문근거형', '윗글의 내용으로 알 수 있는 것은?', NULL, 'C', '[{"choice_id":"A","text":"올챙이는 이미 완전한 개구리가 되었다.","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"시제 표현 오해"},{"choice_id":"B","text":"물고기는 올챙이와 헤어지는 것을 좋아한다.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"문맥적 의미(반대 감정) 추론 오류"},{"choice_id":"C","text":"올챙이는 개구리가 되기를 기다리고 있다.","vector":{"문장 독해력":10},"error_path":"정답"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_Q02', 'S1_LIT_P1', 'sohssure', '논리추론형', '물고기가 \'조금 슬프네\'라고 말한 이유는 무엇일까요?', NULL, 'A', '[{"choice_id":"A","text":"친구인 올챙이와 물속에서 헤어져야 하기 때문에","vector":{"논리 사고력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"올챙이에게 다리가 생긴 모습이 무서워서","vector":{"어휘력":-5,"국어 개념 적용 능력":-5},"error_path":"인물 심리 파악 오류"},{"choice_id":"C","text":"자신은 영원히 올챙이로 남아야 해서","vector":{"논리 사고력":-5},"error_path":"인과 관계 비약"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_Q03', 'S1_LIT_P1', 'sohssure', '어휘단독형', '다음 문장의 빈칸에 들어갈 낱말의 표기가 바른 것은 무엇인가요?', '내가 개구리가 되어서 너를 (          ).', 'E', '[{"choice_id":"A","text":"기달릴게","error_path":"\'기다리다\'는 \'기달리다\'가 아니라 \'기다리다\'가 올바른 표현입니다.","vector":{"어법·문법 능력":-3,"어휘력":-2}},{"choice_id":"B","text":"기다릴께","error_path":"\'ㄹ게\'는 소리 나는 대로 \'ㄹ께\'로 적지 않습니다.","vector":{"어법·문법 능력":-3,"어휘력":-2}},{"choice_id":"C","text":"기달릴께","error_path":"잘못된 표기입니다.","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"D","text":"기다려줄께","error_path":"\'줄게\'가 맞습니다.","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"E","text":"기다릴게","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_Q04', 'S1_LIT_P1', 'sohssure', '논리추론형', '올챙이가 개구리가 되는 순서로 알맞은 것은?', NULL, 'C', '[{"choice_id":"A","text":"꼬리가 짧아진다 -> 앞다리가 나온다 -> 뒷다리가 나온다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"꼬리 변화가 가장 먼저라고 오해"},{"choice_id":"B","text":"뒷다리와 앞다리가 동시에 나온다","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"순차적 변화를 동시 발생으로 오해"},{"choice_id":"C","text":"뒷다리가 나온다 -> 앞다리가 나온다 -> 꼬리가 짧아진다","vector":{"구조 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"D","text":"앞다리가 나온다 -> 뒷다리가 나온다 -> 꼬리가 길어진다","vector":{"구조 독해력":-5,"비문학 배경지식":-5},"error_path":"순서를 반대로 알고 꼬리 변화를 오해"},{"choice_id":"E","text":"알에서 바로 개구리로 변한다","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"변태 과정을 생략한 오해"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_Q05', 'S1_LIT_P1', 'sohssure', '어휘단독형', '이 글에서 \'쑥\'은 어떤 모습일까요?', NULL, 'D', '[{"choice_id":"A","text":"소리를 지르는 모양","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"청각적 묘사로 오해"},{"choice_id":"B","text":"천천히 아주 느리게 움직이는 모양","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"반대되는 속도감(느림)과 혼동"},{"choice_id":"C","text":"빙글빙글 도는 모양","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"회전하는 동작으로 오해"},{"choice_id":"D","text":"갑자기 밖으로 나오는 모양","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"E","text":"작아지는 모양","vector":{"어휘력":-5,"비문학 배경지식":-5},"error_path":"성장(커짐/나옴)의 반대 의미 선택"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_Q06', 'S1_LIT_P1', 'sohssure', '지문근거형', '올챙이의 몸에서 가장 먼저 나온 것은 무엇인가요?', NULL, 'B', '[{"choice_id":"A","text":"날개","vector":{"어휘력":-5,"비문학 배경지식":-5},"error_path":"개구리에게 없는 기관 선택"},{"choice_id":"B","text":"뒷다리","vector":{"문장 독해력":10},"error_path":"정답"},{"choice_id":"C","text":"앞다리","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"뒷다리 다음 단계를 먼저라고 오해"},{"choice_id":"D","text":"꼬리","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"원래 있던 꼬리를 새로 나온 것으로 오해"},{"choice_id":"E","text":"지느러미","vector":{"어휘력":-5,"비문학 배경지식":-5},"error_path":"물고기의 기관과 혼동"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_Q07', 'S1_LIT_P1', 'sohssure', '지문근거형', '엄마 개구리의 말에 따르면, 올챙이가 개구리가 되면 꼬리는 어떻게 되나요?', NULL, 'A', '[{"choice_id":"A","text":"점점 짧아진다","vector":{"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"다리로 변한다","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"잘못된 변태 과정 추측"},{"choice_id":"C","text":"두 개로 갈라진다","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"본문에 없는 엉뚱한 변화 선택"},{"choice_id":"D","text":"점점 길어진다","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"반대 변화(길어짐) 선택"},{"choice_id":"E","text":"색깔이 변한다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"언급되지 않은 변화 선택"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_Q08', 'S1_LIT_P1', 'sohssure', '논리추론형', '올챙이가 친구 물고기에게 한 약속은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"개구리가 되어도 자주 놀러 오겠다는 약속","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"엄마 말을 잘 듣겠다는 약속","vector":{"문장 독해력":-5},"error_path":"물고기가 아닌 엄마와의 관계 추측"},{"choice_id":"C","text":"맛있는 먹이를 주겠다는 약속","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문에 없는 내용(행동:먹이주기) 선택"},{"choice_id":"D","text":"절대 개구리가 되지 않겠다는 약속","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지킬 수 없는 약속을 선택"},{"choice_id":"E","text":"물고기에게 수영을 배우겠다는 약속","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문에 없는 내용(행동:수영) 선택"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_Q09', 'S1_LIT_P1', 'sohssure', '서술형', '친구가 슬퍼할 때 올챙이가 한 말은 무엇인지 지문에서 찾아 쓰시오.', NULL, NULL, '[]', '"걱정 마. 내가 개구리가 되어도 자주 연못에 놀러 올게."', '[{"criteria_id":1,"condition":"올챙이가 한 말을 지문에서 정확하게 찾아 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_Q10', 'S1_LIT_P1', 'sohssure', '서술형', '올챙이의 뒷다리가 나온 것을 보고 친구 물고기가 뭐라고 말했는지 쓰시오.', NULL, NULL, '[]', '"축하해, 올챙이야. 하지만 개구리가 되면 우리랑 헤어져야 하니 조금 슬프네."', '[{"criteria_id":1,"condition":"물고기의 말을 지문에서 찾아 비슷하게 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q01', 'S1_LIT_P2', 'sohssure', '지문근거형', '(가)에서 물 한 모금을 마시고 하늘을 쳐다보는 동물은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"닭","vector":{"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"사람","vector":{"문장 독해력":-5,"국어 개념 적용 능력":-5},"error_path":"의인화 파악 실패 (행동의 주체를 사람으로 단정)"},{"choice_id":"C","text":"개구리","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"대상 파악 오류 (지문에 없는 대상 상상)"},{"choice_id":"D","text":"반딧불","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"작품 간 혼동 (나)의 대상을 (가)로 착각"},{"choice_id":"E","text":"구름","vector":{"문장 독해력":-5,"구조 독해력":-5},"error_path":"주어-목적어 혼동 (쳐다보는 대상을 주어로 착각)"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q02', 'S1_LIT_P2', 'sohssure', '지문근거형', '(나)에서 화자가 \'반딧불\'을 보러 가자고 한 때는 언제인가요?', NULL, 'E', '[{"choice_id":"A","text":"대낮","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"상식 오류 (\'반딧불\'은 밤에 보임) 및 어휘 무시"},{"choice_id":"B","text":"비 오는 날","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"근거 없는 정보 개입 (지문에 없는 날씨 상상)"},{"choice_id":"C","text":"보름밤","vector":{"어휘력":-5,"국어 관련 배경지식":-5},"error_path":"어휘 혼동 (그믐 vs 보름) 및 \'달조각\' 표현 오독"},{"choice_id":"D","text":"이른 아침","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"맥락 파악 오류 (어두워야 반딧불이 보임)"},{"choice_id":"E","text":"그믐밤","vector":{"어휘력":10},"error_path":"정답"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q03', 'S1_LIT_P2', 'sohssure', '어휘단독형', '다음 문장의 괄호 안에 들어갈 낱말을 바르게 쓴 것은 무엇인가요?', '달조각을 (          ) 가자.', 'D', '[{"choice_id":"A","text":"줏으러","error_path":"옛말/방언 혼동 (표준어 아님)","vector":{"어법·문법 능력":-3,"어휘력":-2}},{"choice_id":"B","text":"주으러","error_path":"불규칙 활용 오류 (흔한 실수)","vector":{"어법·문법 능력":-3,"어휘력":-2}},{"choice_id":"C","text":"줍으러","error_path":"기본형 \'줍다\'를 그대로 활용하려 함 (심각한 활용 오류)","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"D","text":"주우러","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}},{"choice_id":"E","text":"주러","error_path":"다른 단어 \'주다\'와 혼동","vector":{"어법·문법 능력":-5,"어휘력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q04', 'S1_LIT_P2', 'sohssure', '논리추론형', '(가)에서 닭이 물을 먹고 하늘을 쳐다보는 이유는 무엇일까요? (가장 적절한 감상)', NULL, 'A', '[{"choice_id":"A","text":"물을 주신 하늘에 감사하는 마음으로","vector":{"논리 사고력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"B","text":"목이 아파서","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"문학적 상황을 생물학적/현실적 문제로 오해"},{"choice_id":"C","text":"구름의 개수를 세어 보려고","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"지엽적 정보(구름)에 집착한 단순 추론"},{"choice_id":"D","text":"구름이 먹고 싶어서","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"상식 및 문맥 파악의 심각한 오류"},{"choice_id":"E","text":"하늘에 날아가는 새가 부러워서","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"근거 없는 인과 관계 추론"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q05', 'S1_LIT_P2', 'sohssure', '지문근거형', '(나)에서 \'부서진 달조각\'은 무엇을 가리키는 말인가요?', NULL, 'B', '[{"choice_id":"A","text":"깨진 유리","vector":{"국어 개념 적용 능력":-5,"어휘력":-5},"error_path":"비유적 표현의 문자적 해석 오류 (Metaphor Literalism)"},{"choice_id":"B","text":"반딧불","vector":{"국어 개념 적용 능력":10,"어휘력":10},"error_path":"정답"},{"choice_id":"C","text":"물방울","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"시각적 이미지의 자의적 연결 (빛나는 것=물방울)"},{"choice_id":"D","text":"별","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"지문에 없는 대상 연상 (유사 소재 혼동)"},{"choice_id":"E","text":"돌멩이","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"맥락과 무관한 사물 선택 (부서진 것=돌)"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q06', 'S1_LIT_P2', 'sohssure', '논리추론형', '(나)의 화자(말하는 이)가 친구에게 하고 싶은 말로 가장 알맞은 것은 무엇인가요?', NULL, 'B', '[{"choice_id":"A","text":"반딧불 잡아다가 불을 켜자.","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"형설지공(螢雪之功) 고사의 과도한 적용 및 기능적 해석"},{"choice_id":"B","text":"우리 같이 숲으로 가서 반딧불을 찾자.","vector":{"국어 개념 적용 능력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"C","text":"숲은 위험하니까 절대 가면 안 돼.","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"정서/태도 파악 오류 (제안과 반대되는 금지)"},{"choice_id":"D","text":"숲을 깨끗하게 청소하자.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"도덕적 당위의 부적절한 개입 (Camouflage Disguise)"},{"choice_id":"E","text":"달조각을 주워서 팔러 가자.","vector":{"국어 관련 배경지식":-5,"논리 사고력":-5},"error_path":"동심적 상황에 대한 세속적/경제적 해석 오류"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q07', 'S1_LIT_P2', 'sohssure', '어휘단독형', '(나)의 \'달조각을 주우러\'에서 \'주우러\'와 바꿔 쓰기에 가장 알맞은 말은?', NULL, 'B', '[{"choice_id":"A","text":"버리러","vector":{"어휘력":-5},"error_path":"반의어 선택 오류"},{"choice_id":"B","text":"찾으러","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"C","text":"모으러","vector":{"어휘력":-5},"error_path":"유사 의미어의 미세한 뉘앙스 차이 (단순 수집 vs 탐색 후 습득)"},{"choice_id":"D","text":"만들러","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"행위의 성격 파악 오류 (발견 vs 제작)"},{"choice_id":"E","text":"먹으러","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"동심적 표현(달조각)을 식욕/음식으로 오해"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q08', 'S1_LIT_P2', 'sohssure', '논리추론형', '(가)를 읽고 떠오르는 생각이나 느낌으로 알맞은 것은?', NULL, 'C', '[{"choice_id":"A","text":"하늘이 무너질까 봐 걱정스러워.","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"기우(杞憂) 고사성어의 부적절한 개입 및 과도한 상상"},{"choice_id":"B","text":"할 일이 없어서 심심해 보여.","vector":{"논리 사고력":-5,"국어 개념 적용 능력":-5},"error_path":"행위의 의미(물 마심=생존/감사) 파악 실패"},{"choice_id":"C","text":"작은 일에도 감사하는 마음이 느껴져.","vector":{"국어 개념 적용 능력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"D","text":"빨리 물을 마셔야 해서 급한 느낌이야.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"정서 파악 오류 (여유로움 vs 조급함)"},{"choice_id":"E","text":"혼자 있어서 외롭고 쓸쓸해 보여.","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"객관적 상황을 부정적 정서(고독)로 왜곡"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q09', 'S1_LIT_P2', 'sohssure', '서술형', '(가) 시에서 닭은 물 한 모금을 마시고 무엇을 쳐다보는지 두 가지를 찾아 쓰시오.', NULL, NULL, '[]', '하늘, 구름', '[{"criteria_id":1,"condition":"하늘과 구름(또는 둘 중 하나)을 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P2_Q10', 'S1_LIT_P2', 'sohssure', '서술형', '(나) 시에서 친구들은 숲으로 무엇을 주우러 가자고 했는지 쓰시오.', NULL, NULL, '[]', '달조각 (또는 반딧불)', '[{"criteria_id":1,"condition":"달조각 또는 반딧불을 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q01', 'S1_LIT_P3', 'sohssure', '지문근거형', '(가)에서 말하는 이가 살고 싶어 하는 곳은 어디인가요?', NULL, 'D', '[{"choice_id":"A","text":"뒷문 밖","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문 속 장소(갈잎의 노래가 있는 곳)를 목적지로 착각"},{"choice_id":"B","text":"깊은 산속","vector":{"비문학 배경지식":-5,"문장 독해력":-5},"error_path":"일반적인 은거지 이미지에 기댄 추측 오류"},{"choice_id":"C","text":"도시","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"시의 정서(자연)와 정반대되는 공간 선택"},{"choice_id":"D","text":"강변","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"E","text":"바닷가","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"\'금모래\'라는 단어에서 연상된 오답"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q02', 'S1_LIT_P3', 'sohssure', '어휘단독형', '(나)의 \'하얀 쪽배\'에서 \'쪽배\'의 뜻으로 가장 알맞은 것은?', NULL, 'E', '[{"choice_id":"A","text":"맛있는 과일","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"\'배\'의 동음이의어(과일) 혼동"},{"choice_id":"B","text":"물건을 파는 가게","vector":{"어휘력":-5,"국어 관련 배경지식":-5},"error_path":"\'배\'라는 글자의 동음이의어 혼동 또는 문맥 상실"},{"choice_id":"C","text":"하늘을 나는 비행기","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"은하수/하늘이라는 배경에만 주목하여 운송수단 오해"},{"choice_id":"D","text":"아주 큰 여객선","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"단어의 뜻(작다)과 정반대되는 크기 선택"},{"choice_id":"E","text":"작고 좁은 배","vector":{"어휘력":10},"error_path":"정답"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q03', 'S1_LIT_P3', 'sohssure', '어휘단독형', '다음 문장의 빈칸에 들어갈 낱말로 알맞은 것은 무엇인가요?', '쪽배에 꿈을 (          ) 은하수로 갔다.', 'D', '[{"choice_id":"A","text":"씯고","error_path":"없는 말","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"B","text":"싿고","error_path":"어휘 의미 혼동","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"C","text":"실고","error_path":"\'ㄹ\' 받침 오류 (불규칙 활용 미숙지)","vector":{"어법·문법 능력":-3,"어휘력":-2}},{"choice_id":"D","text":"싣고","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}},{"choice_id":"E","text":"싯고","error_path":"받침 오류 (심각)","vector":{"어법·문법 능력":-5,"어휘력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q04', 'S1_LIT_P3', 'sohssure', '논리추론형', '(가)에서 첫 번째 행과 마지막 행이 같은 것은 어떤 효과를 주나요?', NULL, 'A', '[{"choice_id":"A","text":"운율을 형성하고 의미를 강조한다","vector":{"구조 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"B","text":"글을 읽는 속도를 빠르게 한다","vector":{"구조 독해력":-5,"국어 관련 배경지식":-5},"error_path":"반복의 기능(안정감)과 반대되는 효과(속도감) 선택"},{"choice_id":"C","text":"새로운 사건이 시작됨을 암시한다","vector":{"논리 사고력":-5,"구조 독해력":-5},"error_path":"반복의 의미(지속/강조)와 상충되는 해석(새로운 시작)"},{"choice_id":"D","text":"이야기가 끝났음을 알려 준다","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"단순한 종료 신호로 오해 (수미상관의 구조적 미학 간과)"},{"choice_id":"E","text":"등장인물의 성격이 변했음을 보여 준다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"동일한 소망의 반복을 성격 변화로 잘못 해석"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q05', 'S1_LIT_P3', 'sohssure', '지문근거형', '(나)에서 길을 잃지 않게 도와주는 \'등대\' 역할을 하는 것은 무엇인가요?', NULL, 'C', '[{"choice_id":"A","text":"돛대","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"배의 부속품(없는 것)을 있는 것으로 착각"},{"choice_id":"B","text":"계수나무","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"본문에 나오는 다른 소재와 혼동 (배 안에 있는 사물)"},{"choice_id":"C","text":"샛별","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"D","text":"은하수","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"배경 공간을 길잡이 역할로 오해"},{"choice_id":"E","text":"토끼","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"본문의 등장 동물을 길잡이로 오해"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q06', 'S1_LIT_P3', 'sohssure', '논리추론형', '(가)와 (나)를 읽고 난 뒤의 느낌으로 가장 알맞은 것은?', NULL, 'D', '[{"choice_id":"A","text":"화가 나고 답답하다","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"부정적인 감정으로 오해"},{"choice_id":"B","text":"시끄럽고 정신이 없다","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"고요하고 정적인 분위기를 오해"},{"choice_id":"C","text":"슬프고 눈물이 날 것 같다","vector":{"문장 독해력":-5,"국어 관련 배경지식":-5},"error_path":"일반적인 이별 노래의 정서를 잘못 적용"},{"choice_id":"D","text":"아름답고 평화로운 느낌이 든다","vector":{"문장 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"무섭고 조마조마한 느낌이 든다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"정서와 정반대되는 감정 (공포)"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q07', 'S1_LIT_P3', 'sohssure', '어휘단독형', '(가)의 \'갈잎\'은 무엇의 줄임말인가요?', NULL, 'C', '[{"choice_id":"A","text":"가을 잎","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"비슷한 발음(가을)에서 유추한 오답"},{"choice_id":"B","text":"가는 잎","vector":{"어휘력":-5,"구조 독해력":-5},"error_path":"모양(가늘다)에서 유추한 오답"},{"choice_id":"C","text":"갈대 잎","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"D","text":"갈라진 잎","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"형태(갈라지다)에서 유추한 오답"},{"choice_id":"E","text":"갈색 잎","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"색깔(갈색)에서 유추한 오답"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q08', 'S1_LIT_P3', 'sohssure', '논리추론형', '(나)에서 \'구름 나라\'는 어떤 곳일까요? 가장 알맞은 상상을 골라 보세요.', NULL, 'E', '[{"choice_id":"A","text":"자동차들이 쌩쌩 달리는 도로","vector":{"어휘력":-5,"국어 관련 배경지식":-5},"error_path":"현실 세계의 복잡한 모습을 잘못 투영"},{"choice_id":"B","text":"아무것도 없는 텅 빈 사막","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"구름/은하수/계수나무 등 풍부한 소재를 무시"},{"choice_id":"C","text":"시끄럽고 먼지가 많은 공사장","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"깨끗하고 푸른 하늘 이미지와 정반대"},{"choice_id":"D","text":"무섭고 캄캄한 동굴 같은 곳","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"반짝이는 샛별/은하수 이미지와 정반대"},{"choice_id":"E","text":"꿈속처럼 신비롭고 재미있는 곳","vector":{"논리 사고력":10,"문장 독해력":10},"error_path":"정답"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q09', 'S1_LIT_P3', 'sohssure', '서술형', '(가) 시에서 \'뜰\'과 \'뒷문 밖\'에 각각 무엇이 있다고 했는지 찾아 쓰시오.', NULL, NULL, '[]', '뜰에는 금모래 빛, 뒷문 밖에는 갈잎의 노래', '[{"criteria_id":1,"condition":"금모래 빛과 갈잎의 노래를 정확하게 찾아 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P3_Q10', 'S1_LIT_P3', 'sohssure', '서술형', '(나) 시에서는 무엇이 \'등대\' 역할을 한다고 했는지 쓰시오.', NULL, NULL, '[]', '샛별', '[{"criteria_id":1,"condition":"\'샛별\'이라고 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q01', 'S1_LIT_P4', 'sohssure', '지문근거형', '(가)에서 동생이 지난밤에 한 행동은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"이불에 오줌을 쌌다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"정말로 지도를 그렸다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"비유적 표현(지도)을 사실적 행위(그림 그리기)로 오해"},{"choice_id":"C","text":"빨래를 걷어 왔다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"배경(빨랫줄)을 주체의 행동으로 오해"},{"choice_id":"D","text":"진짜로 돈을 주웠다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"꿈속의 내용을 현실의 행동으로 착각"},{"choice_id":"E","text":"형과 싸웠다","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"지문에 없는 내용을 상상"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q02', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)에서 동생이 아침에 \'소금\'을 얻으러 간 이유는 무엇일까요?', NULL, 'A', '[{"choice_id":"A","text":"오줌을 싼 벌로 심부름을 가서","vector":{"국어 관련 배경지식":10,"논리 사고력":10},"error_path":"정답 (한국의 전통 풍습 배경지식 활용)"},{"choice_id":"B","text":"아침 반찬을 만들어야 해서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"소금의 일상적 용도(요리)만 생각"},{"choice_id":"C","text":"꿈속에서 돈을 잃어버려서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"꿈 내용과 현실 행동을 잘못 연결"},{"choice_id":"D","text":"빨래를 깨끗하게 하려고","vector":{"논리 사고력":-5,"구조 독해력":-5},"error_path":"빨랫줄 이미지와 소금의 세탁 효과(일반상식) 혼동"},{"choice_id":"E","text":"지도를 그리기 위해서","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"소금과 지도 그리기의 인과 관계 오류"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q03', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)에서 \'지도\'는 실제로 무엇을 가리키나요?', NULL, 'A', '[{"choice_id":"A","text":"이불에 오줌을 싼 자국","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"우리나라의 모습","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"지도의 사전적 의미만 생각"},{"choice_id":"C","text":"보물섬으로 가는 길","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"꿈속 내용(돈 주워 넣고)과 상상을 혼동"},{"choice_id":"D","text":"동생이 그린 그림","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"\'그린\'이라는 표현을 곧이곧대로 해석"},{"choice_id":"E","text":"아침에 해가 뜨는 모양","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문과 관계없는 내용 선택"}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q04', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)를 읽을 때 느껴지는 리듬감에 대한 설명으로 알맞은 것은?', NULL, 'A', '[{"choice_id":"A","text":"\'오줌 쏴 눈 지도\'라는 말이 반복되어 리듬이 생긴다","vector":{"구조 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답 (반복을 통한 운율 형성)"},{"choice_id":"B","text":"글자 수가 모두 똑같아서 리듬이 생긴다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"글자 수(음수율)의 변화(3/4조 등)를 무시하고 획일적으로 판단"},{"choice_id":"C","text":"이야기를 하듯이 길게 이어져서 리듬이 없다","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"운율이 있는 시를 산문으로 오해"},{"choice_id":"D","text":"아무런 반복이 없어서 리듬이 느껴지지 않는다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"명백히 존재하는 반복을 파악하지 못함"},{"choice_id":"E","text":"첫 글자가 모두 같아서 리듬이 생긴다","vector":{"구조 독해력":-5,"어휘력":-5},"error_path":"두운(첫 글자 반복)이 나타나지 않는데 있다고 착각"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q05', 'S1_LIT_P4', 'sohssure', '논리추론형', '(나)에서 \'파 보나 마나\'라고 말한 이유는 무엇일까요?', NULL, 'A', '[{"choice_id":"A","text":"꽃의 색깔과 감자의 색깔이 똑같아서","vector":{"논리 사고력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"감자를 파는 것이 귀찮아서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"화자의 태도(게으름)로 오해"},{"choice_id":"C","text":"감자가 아직 다 자라지 않아서","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"농사 지식(수확 시기)과 혼동"},{"choice_id":"D","text":"누가 이미 감자를 다 캐가서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문에 없는 상황 상상"},{"choice_id":"E","text":"감자 꽃이 시들어 버려서","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"꽃의 상태를 이유로 착각"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q06', 'S1_LIT_P4', 'sohssure', '어휘단독형', '(나)에서 \'파 보나 마나\'라는 말의 뜻으로 가장 알맞은 것은?', NULL, 'A', '[{"choice_id":"A","text":"결과가 뻔해서 확인할 필요도 없이","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"B","text":"땅을 파는 것이 너무 힘들어서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"행위의 어려움으로 오해"},{"choice_id":"C","text":"아무리 파 봐도 알 수가 없어서","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"의미를 반대(불확실성)로 해석"},{"choice_id":"D","text":"조금만 파도 금방 나오기 때문에","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"시간의 빠름으로 오해"},{"choice_id":"E","text":"남들이 보지 않을 때 몰래","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"비밀스러운 행동으로 오해"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q07', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)와 (나)를 읽을 때 드는 느낌으로 가장 알맞은 것은?', NULL, 'A', '[{"choice_id":"A","text":"재미있고 웃음이 난다","vector":{"문장 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답 (해학적 정서)"},{"choice_id":"B","text":"슬프고 눈물이 난다","vector":{"문장 독해력":-5,"국어 관련 배경지식":-5},"error_path":"정반대의 정서(비극) 선택"},{"choice_id":"C","text":"무섭고 깜짝 놀란다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"공포/놀람으로 오해"},{"choice_id":"D","text":"지루하고 하품이 난다","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"감상의 부재 또는 흥미 없음 선택"},{"choice_id":"E","text":"화가 나고 답답하다","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"부정적 정서(분노) 선택"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q08', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)와 (나)에 공통으로 나오는 소재는 아니지만, 둘 다 우리 주변에서 흔히 볼 수 있는 것은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"가족과 자연","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답 ((가) 동생/오줌, (나) 감자/꽃 - 일상적 소재)"},{"choice_id":"B","text":"전쟁과 군인","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"전혀 다른 무거운 주제 선택"},{"choice_id":"C","text":"왕자와 공주","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"동화 속 환상적인 소재 오해"},{"choice_id":"D","text":"우주선과 외계인","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"SF적 소재 오해"},{"choice_id":"E","text":"로봇과 컴퓨터","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"현대 기술 문명 소재 오해"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q09', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)의 \'동생\'에게 해주고 싶은 말로 알맞은 것은?', NULL, 'A', '[{"choice_id":"A","text":"괜찮아, 다음부터는 자기 전에 화장실에 다녀오렴","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답 (따뜻한 위로와 조언)"},{"choice_id":"B","text":"지도를 아주 잘 그렸구나, 화가 해도 되겠다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"상황(실수)을 칭찬하는 엉뚱한 반응"},{"choice_id":"C","text":"꿈속에서 돈을 잃어버려서 정말 안타깝다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"핵심 사건(오줌)이 아닌 꿈 내용에만 반응"},{"choice_id":"D","text":"소금을 더 많이 받아와야지","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"벌을 더 받으라는 부정적 반응"},{"choice_id":"E","text":"빨래는 네가 다 해야 해","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지나치게 가혹한 반응"}]', NULL, NULL, NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_LIT_P4_Q10', 'S1_LIT_P4', 'sohssure', '논리추론형', '(가)와 (나)에 대한 설명으로 알맞지 않은 것은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"(나)는 감자 꽃의 색깔이 감자의 색깔과 다르다고 말한다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답 (틀린 내용 찾기: 같다고 말함)"},{"choice_id":"B","text":"(가)는 4행시처럼 \'지도\'라는 말로 끝난다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 전제 누락"},{"choice_id":"C","text":"(가)의 \'지도\'는 오줌을 싼 자국을 빗댄 말이다","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"부정형 문항 오독: 인과 관계 왜곡"},{"choice_id":"D","text":"(나)의 자주 감자는 자주 꽃이 핀다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 조건 혼동"},{"choice_id":"E","text":"(가)와 (나)는 모두 짧지만 의미가 담겨 있다","vector":{"국어 개념 적용 능력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 범위 과확대"}]', NULL, NULL, NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_Q01', 'S1_NON_P1', 'sohssure', '지문근거형', '나비가 자라는 순서로 알맞은 것은 무엇인가요?', NULL, 'B', '[{"choice_id":"A","text":"알 → 지렁이 → 번데기 → 나비","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"대상(애벌레) 지칭 어휘 오해"},{"choice_id":"B","text":"알 → 애벌레 → 번데기 → 어른벌레","vector":{"구조 독해력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"C","text":"알 → 번데기 → 애벌레 → 어른벌레","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"시간적 순서 구조 파악 오류"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_Q02', 'S1_NON_P1', 'sohssure', '논리추론형', '갓 나온 나비가 바로 날지 못하는 이유는 무엇일까요?', NULL, 'B', '[{"choice_id":"A","text":"비가 와서 날개가 젖었기 때문에","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"존재하지 않는 상식(비)의 부적절한 개입"},{"choice_id":"B","text":"날개가 젖어 있어서 말라야 하기 때문에","vector":{"논리 사고력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"C","text":"너무 오랫동안 번데기로 있어서 힘이 없어서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"인과 관계 정보 문장 오독"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_Q03', 'S1_NON_P1', 'sohssure', '어휘단독형', '다음 문장의 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?', '나비가 잎사귀에 알을 (          ).', 'E', '[{"choice_id":"A","text":"낮았습니다","error_path":"\'낮다(Low)\'와 혼동했습니다.","vector":{"어법·문법 능력":-3,"어휘력":-3}},{"choice_id":"B","text":"나았습니다","error_path":"\'낫다(Recover)\'와 혼동했습니다.","vector":{"어법·문법 능력":-3,"어휘력":-3}},{"choice_id":"C","text":"났았습니다","error_path":"없는 말입니다. 심각한 표기 오류.","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"D","text":"나앟습니다","error_path":"어휘 의미 혼동","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"E","text":"낳았습니다","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}}]', NULL, NULL, NULL, 3);
