INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q03', 'S1_NON_P2', 'sohssure', '어휘단독형', '다음 문장의 빈칸에 들어갈 말로 알맞은 것은 무엇인가요?', '토끼 귀는 몸의 열을 (          ) 줍니다.', 'B', '[{"choice_id":"A","text":"씻겨","error_path":"\'씻기다\'와 혼동 (문맥 파악 실패)","vector":{"어법·문법 능력":-2,"문장 독해력":-3}},{"choice_id":"B","text":"식혀","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}},{"choice_id":"C","text":"시켜","error_path":"\'시키다\'와 혼동 (발음 유사)","vector":{"어법·문법 능력":-3,"어휘력":-3}},{"choice_id":"D","text":"시겨","error_path":"없는 말 (심각한 철자 오류)","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"E","text":"식여","error_path":"어휘 의미 혼동","vector":{"어법·문법 능력":-5,"어휘력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q04', 'S1_NON_P2', 'sohssure', '지문근거형', '더운 여름에 토끼의 큰 귀는 어떤 역할을 하나요?', NULL, 'D', '[{"choice_id":"A","text":"다른 동물들에게 예쁘게 보이게 해요.","vector":{"국어 개념 적용 능력":-5,"논리 사고력":-5},"error_path":"심미적 기능에 대한 주관적 판단 개입"},{"choice_id":"B","text":"부채처럼 흔들어서 바람을 만들어요.","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"유사 기능(시원함)에 대한 물리적 오개념 (부채질)"},{"choice_id":"C","text":"햇볕을 가려서 그늘을 만들어요.","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"형태적 특징(크다)에 기반한 자의적 추측 (그늘막)"},{"choice_id":"D","text":"몸의 열을 밖으로 내보내 시원하게 해 줘요.","vector":{"문장 독해력":10,"어휘력":10},"error_path":"정답"},{"choice_id":"E","text":"빗물을 받아서 마실 수 있게 해요.","vector":{"비문학 배경지식":-5,"문장 독해력":-5},"error_path":"지문과 무관한 기능 상상 (물 컵)"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q05', 'S1_NON_P2', 'sohssure', '어휘단독형', '이 글에서 \'식혀 주는\'과 바꿔 쓰기에 가장 알맞은 말은 무엇인가요?', NULL, 'C', '[{"choice_id":"A","text":"만들어 주는","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"문맥상 반대 의미 선택 (제거 vs 생성)"},{"choice_id":"B","text":"참아 주는","vector":{"어휘력":-5,"국어 개념 적용 능력":-5},"error_path":"단어의 주체 혼동 (참는 것은 생물, 여기선 기능)"},{"choice_id":"C","text":"없애 주는","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"D","text":"더해 주는","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"문맥상 반대 의미 선택 (감소 vs 증가)"},{"choice_id":"E","text":"피해 주는","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"유사 문맥(피하다)과의 혼동"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q06', 'S1_NON_P2', 'sohssure', '논리추론형', '글쓴이가 토끼의 귀를 \'보물\'이라고 표현한 이유는 무엇인가요?', NULL, 'D', '[{"choice_id":"A","text":"친구들이 서로 가지고 싶어 해서","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"희소성에 기반한 소유욕으로 오해"},{"choice_id":"B","text":"시장에 내다 팔면 비싼 값을 받을 수 있어서","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"\'보물\'의 경제적 가치에만 주목한 해석 오류"},{"choice_id":"C","text":"땅속 깊은 곳에 숨겨져 있어서","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"\'보물 찾기\' 놀이와의 혼동"},{"choice_id":"D","text":"토끼의 생명을 지켜 주는 중요한 것이라서","vector":{"논리 사고력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"보석처럼 반짝반짝 빛이 나서","vector":{"문장 독해력":-5,"국어 개념 적용 능력":-5},"error_path":"비유적 표현의 시각적/문자적 해석 오류"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q07', 'S1_NON_P2', 'sohssure', '논리추론형', '다음 문장에 들어갈 말로 가장 알맞은 것은 무엇인가요?\n"토끼는 숲속에서 약한 동물이에요. (    ) 적이 나타나면 빨리 도망가야 해요."', NULL, 'C', '[{"choice_id":"A","text":"왜냐하면","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"인과 관계의 방향 혼동 (결과가 뒤에 오는데 원인을 이끄는 말 선택)"},{"choice_id":"B","text":"하지만","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"문맥 파악 오류 (인과 관계를 대조 관계로 오해)"},{"choice_id":"C","text":"그래서","vector":{"구조 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"D","text":"그리고","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"문맥 파악 오류 (인과 관계를 단순 나열로 오해)"},{"choice_id":"E","text":"만약","vector":{"어휘력":-5,"구조 독해력":-5},"error_path":"가정 상황을 나타내는 말로 오해 (사실 진술임)"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q08', 'S1_NON_P2', 'sohssure', '논리추론형', '글의 내용으로 미루어 볼 때, 토끼의 특징으로 알맞은 것은 무엇인가요?', NULL, 'E', '[{"choice_id":"A","text":"몸집이 커서 호랑이와 싸워 이길 수 있다.","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"전제(약한 동물)를 부정하는 심각한 독해 오류"},{"choice_id":"B","text":"다리가 짧아서 적에게 잡히기 쉽다.","vector":{"논리 사고력":-5,"비문학 배경지식":-5},"error_path":"행동 결과(빨리 도망간다)와 모순되는 추론"},{"choice_id":"C","text":"귀가 작아서 소리를 잘 듣지 못한다.","vector":{"문장 독해력":-5,"구조 독해력":-5},"error_path":"지문(귀가 길다, 잘 듣는다)과 정반대 사실 선택"},{"choice_id":"D","text":"땀을 아주 많이 흘려서 더위를 식힌다.","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"지문 정보(땀 안 흘림)의 정반대 선택"},{"choice_id":"E","text":"땀을 흘리는 대신 귀로 열을 내보낸다.","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q09', 'S1_NON_P2', 'sohssure', '서술형', '토끼의 귀는 소리를 듣는 일 말고 어떤 일을 하는지 지문에서 한 가지만 찾아 쓰시오.', NULL, NULL, '[]', '더위를 식혀 줍니다. (또는 몸의 열을 밖으로 내보냅니다.)', '[{"criteria_id":1,"condition":"더위를 식히거나 열을 내보낸다는 내용 포함","score":10,"vector":{"문장 독해력":10,"비문학 배경지식":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P2_Q10', 'S1_NON_P2', 'sohssure', '서술형', '글쓴이는 마지막 문단에서 토끼의 귀를 무엇이라고 불렀는지 쓰시오.', NULL, NULL, '[]', '보물 (또는 아주 중요한 보물)', '[{"criteria_id":1,"condition":"\'보물\'이라는 단어를 씀","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q01', 'S1_NON_P3', 'sohssure', '지문근거형', '이 글은 무엇에 대해 설명하고 있나요?', NULL, 'E', '[{"choice_id":"A","text":"바닷속 물고기들의 생활","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"\'바다\'라는 단어에 이끌려 전혀 다른 주제 선택"},{"choice_id":"B","text":"시원한 물을 마시는 법","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"마지막 문장의 세부 정보를 전체 주제로 착각"},{"choice_id":"C","text":"눈과 얼음의 차이점","vector":{"논리 사고력":-5,"구조 독해력":-5},"error_path":"지문 일부분(눈에 대한 언급)을 전체 주제로 확대 해석"},{"choice_id":"D","text":"식물이 잘 자라는 방법","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"마지막 문장의 부수적 효과를 전체 주제로 오해"},{"choice_id":"E","text":"구름과 비가 만들어지는 과정","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q02', 'S1_NON_P3', 'sohssure', '지문근거형', '이 글에서 \'수증기\'에 대한 설명으로 알맞지 않은 것은?', NULL, 'A', '[{"choice_id":"A","text":"눈에 잘 보이고 매우 무겁다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답 (틀린 내용 찾기: \'눈에 보이지 않을 만큼 작고 가볍다\'고 설명됨)"},{"choice_id":"B","text":"물이 햇볕을 받아 변한 것이다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 지문 근거 누락"},{"choice_id":"C","text":"하늘 높이 올라간다","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"부정형 문항 오독: 세부 정보 오독"},{"choice_id":"D","text":"아주 작고 가볍다","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"부정형 문항 오독: 핵심 정보 혼동"},{"choice_id":"E","text":"찬 공기를 만나면 물방울로 변한다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 과도한 일반화"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q03', 'S1_NON_P3', 'sohssure', '어휘단독형', '다음 문장의 괄호 안에 들어갈 말로 알맞은 것은 무엇인가요?', '수증기가 찬 공기와 (          ) 물방울이 되었다.', 'B', '[{"choice_id":"A","text":"부딧쳐","error_path":"받침 오류 (심각)","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"B","text":"부딪쳐","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}},{"choice_id":"C","text":"부딪혀","error_path":"피동/능동 혼동 (문맥상 어색)","vector":{"어법·문법 능력":-2,"문장 독해력":-2}},{"choice_id":"D","text":"부디쳐","error_path":"소리 나는 대로 잘못 쓴 표기","vector":{"어법·문법 능력":-3,"어휘력":-3}},{"choice_id":"E","text":"부딫쳐","error_path":"어휘 의미 혼동","vector":{"어법·문법 능력":-5,"어휘력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q04', 'S1_NON_P3', 'sohssure', '지문근거형', '비가 아니라 \'눈\'이 되어 내리기 위한 조건은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"날씨가 아주 추워야 한다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"햇볕이 아주 강하게 비쳐야 한다","vector":{"논리 사고력":-5,"비문학 배경지식":-5},"error_path":"눈이 녹는 조건을 생성 조건으로 착각"},{"choice_id":"C","text":"바닷물이 더 많이 증발해야 한다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"강수량 증가 원인을 강수 형태 변화 원인으로 오해"},{"choice_id":"D","text":"바람이 아주 세게 불어야 한다","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"강설 조건(기온)을 풍속으로 오해"},{"choice_id":"E","text":"구름이 아주 높이 떠 있어야 한다","vector":{"문장 독해력":-5,"구조 독해력":-5},"error_path":"구름의 위치와 강수의 형태 혼동"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q05', 'S1_NON_P3', 'sohssure', '어휘단독형', '이 글에서 물이 바다, 하늘, 땅을 돌고 도는 것을 무엇에 비유했나요?', NULL, 'C', '[{"choice_id":"A","text":"이사","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"장소를 옮긴다는 점(이동)만 생각한 오답"},{"choice_id":"B","text":"소풍","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"비슷한 개념(놀러감)과 혼동"},{"choice_id":"C","text":"여행","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"D","text":"놀이","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"즐거운 활동이라는 점에서 착각"},{"choice_id":"E","text":"공부","vector":{"논리 사고력":-5,"어휘력":-5},"error_path":"비유적 표현과 전혀 관계없는 단어 선택"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q06', 'S1_NON_P3', 'sohssure', '어휘단독형', '이 글에서 \'둥둥\'은 어떤 모양을 나타내는 말인가요?', NULL, 'A', '[{"choice_id":"A","text":"물이나 공기 중에 가볍게 떠 있는 모양","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"B","text":"아기들이 걷는 모양","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"\'아장아장\'과 같은 의태어와 혼동"},{"choice_id":"C","text":"북을 칠 때 나는 소리","vector":{"어휘력":-5,"국어 관련 배경지식":-5},"error_path":"동음이의어(북소리 둥둥) 혼동 (문맥 무시)"},{"choice_id":"D","text":"바람이 아주 세게 부는 모양","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"\'씽씽\'과 같은 의태어와 혼동"},{"choice_id":"E","text":"무거운 물건이 바닥에 떨어지는 소리","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"\'쿵쿵\'과 같은 소리 흉내말과 혼동"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q07', 'S1_NON_P3', 'sohssure', '지문근거형', '물방울의 여행 덕분에 일어나는 좋은 일은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"식물들이 잘 자라고 시원한 물을 마실 수 있다","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"하늘이 더 높고 파랗게 변한다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문과 관계없는 일반적인 날씨 묘사 선택"},{"choice_id":"C","text":"햇볕이 더 뜨겁게 비친다","vector":{"논리 사고력":-5,"비문학 배경지식":-5},"error_path":"물의 순환과 무관한 자연 현상 선택"},{"choice_id":"D","text":"바닷물이 점점 줄어든다","vector":{"논리 사고력":-5,"비문학 배경지식":-5},"error_path":"순환(유지)의 개념과 반대되는 현상(고갈) 선택"},{"choice_id":"E","text":"구름이 영원히 사라지지 않는다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"과정의 일부(구름)를 영구적인 상태로 오해"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q08', 'S1_NON_P3', 'sohssure', '논리추론형', '물방울이 이동하는 순서로 알맞은 것은?', NULL, 'C', '[{"choice_id":"A","text":"바다 -> 땅 -> 구름 -> 하늘","vector":{"구조 독해력":-5,"비문학 배경지식":-5},"error_path":"비가 내리는 과정(구름->땅)을 반대로 이해"},{"choice_id":"B","text":"하늘 -> 바다 -> 땅 -> 구름","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"순서를 뒤죽박죽 섞음"},{"choice_id":"C","text":"바다 -> 하늘 -> 구름 -> 땅 -> 바다","vector":{"구조 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"D","text":"구름 -> 하늘 -> 바다 -> 땅","vector":{"구조 독해력":-5,"문장 독해력":-5},"error_path":"비가 땅으로 내리는 과정을 생략하거나 순서 오해"},{"choice_id":"E","text":"땅 -> 구름 -> 하늘 -> 바다","vector":{"구조 독해력":-5,"논리 사고력":-5},"error_path":"땅에서 하늘로 바로 올라가는(증발 위치) 오해"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q09', 'S1_NON_P3', 'sohssure', '서술형', '하늘 높이 올라간 수증기가 찬 공기를 만나 변한 작은 물방울들이 많이 모여서 무엇이 되는지 쓰시오.', NULL, NULL, '[]', '구름', '[{"criteria_id":1,"condition":"\'구름\'이라고 씀","score":10,"vector":{"문장 독해력":10,"비문학 배경지식":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P3_Q10', 'S1_NON_P3', 'sohssure', '서술형', '물의 여행 덕분에 우리나 식물이 어떤 도움을 받는지 지문에서 한 가지만 찾아 쓰시오.', NULL, NULL, '[]', '식물이 무럭무럭 자랄 수 있습니다. (또는 우리가 시원한 물을 마실 수 있습니다.)', '[{"criteria_id":1,"condition":"식물이 자라거나 물을 마실 수 있다는 내용 포함","score":10,"vector":{"문장 독해력":10,"비문학 배경지식":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q01', 'S1_NON_P4', 'sohssure', '지문근거형', '자석의 N극이 가리키는 방향은 어디인가요?', NULL, 'A', '[{"choice_id":"A","text":"북쪽","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"남쪽","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"S극이 가리키는 방향과 혼동"},{"choice_id":"C","text":"동쪽","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"지문에 나오지 않는 방향 (해 뜨는 곳) 선택"},{"choice_id":"D","text":"서쪽","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"지문에 나오지 않는 방향 (해 지는 곳) 선택"},{"choice_id":"E","text":"위쪽","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"나침반의 평면 방향이 아닌 수직 방향 오해"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q02', 'S1_NON_P4', 'sohssure', '논리추론형', '자석이 서로 \'밀어내는\' 경우는 언제인가요?', NULL, 'A', '[{"choice_id":"A","text":"같은 극끼리 만났을 때","vector":{"논리 사고력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"다른 극끼리 만났을 때","vector":{"논리 사고력":-5,"비문학 배경지식":-5},"error_path":"인력(끌어당김)의 조건과 혼동"},{"choice_id":"C","text":"철로 된 물건을 만났을 때","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"자석이 붙는 성질만 생각"},{"choice_id":"D","text":"물이 묻었을 때","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"자력과 무관한 환경 요인 선택"},{"choice_id":"E","text":"너무 뜨거워졌을 때","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"자력을 잃는 조건(고급 지식)을 밀어내는 조건으로 오해"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q03', 'S1_NON_P4', 'sohssure', '지문근거형', '이 글에서 설명하는 자석이 쓰인 예가 아닌 것은?', NULL, 'A', '[{"choice_id":"A","text":"유리창을 닦는 걸레","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답 (지문에 언급되지 않은 물건)"},{"choice_id":"B","text":"잘 닫히는 필통 뚜껑","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 지문 근거 누락"},{"choice_id":"C","text":"꽉 닫히는 냉장고 문","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 세부 정보 오독"},{"choice_id":"D","text":"나침반","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"부정형 문항 오독: 핵심 정보 혼동"},{"choice_id":"E","text":"칠판에 종이를 붙이는 도구","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"부정형 문항 오독: 과도한 일반화"}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q04', 'S1_NON_P4', 'sohssure', '논리추론형', '자석의 N극과 S극이 서로 다른 점은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"가리키는 방향이 다르다","vector":{"구조 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"B","text":"자석이 붙는 성질이 다르다","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"자력의 유무(둘 다 있음)를 차이점으로 오해"},{"choice_id":"C","text":"생활 속에서 쓰이는 곳이 다르다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"사용 용도(자석 전체)를 극의 차이로 오해"},{"choice_id":"D","text":"철을 끌어당기는 힘의 세기가 다르다","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"자력의 세기 차이(일반적으로 같음)를 오해"},{"choice_id":"E","text":"모양과 크기가 다르다","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"물리적 형태가 극마다 다르다고 착각"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q05', 'S1_NON_P4', 'sohssure', '어휘단독형', '이 글에서 \'꽉\'이라는 말의 뜻으로 가장 알맞은 것은?', NULL, 'A', '[{"choice_id":"A","text":"틈이 없이 아주 단단하게","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"B","text":"아주 가볍고 부드럽게","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"반의어(느슨하게/가볍게)와 혼동"},{"choice_id":"C","text":"소리가 나지 않게 조용히","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"문맥상 상황(조용함)을 뜻으로 오해"},{"choice_id":"D","text":"멀리 떨어져서","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"\'착\' 달라붙는 것과 반대되는 상황 선택"},{"choice_id":"E","text":"아주 빠르고 신속하게","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"속도를 나타내는 말(\'확\')과 혼동"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q06', 'S1_NON_P4', 'sohssure', '어휘단독형', '이 글에서 \'신기한\'과 비슷한 뜻을 가진 말은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"놀라운","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"B","text":"무거운","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"물리적 무게와 혼동"},{"choice_id":"C","text":"단단한","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"물리적 경도와 혼동"},{"choice_id":"D","text":"오래된","vector":{"어휘력":-5,"비문학 배경지식":-5},"error_path":"시간적 오래됨과 혼동"},{"choice_id":"E","text":"차가운","vector":{"어휘력":-5,"논리 사고력":-5},"error_path":"온도와 혼동"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q07', 'S1_NON_P4', 'sohssure', '논리추론형', '나침반으로 길을 찾을 수 있는 이유는 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"자석의 N극이 항상 북쪽을 가리키기 때문에","vector":{"논리 사고력":10,"비문학 배경지식":10},"error_path":"정답"},{"choice_id":"B","text":"나침반 바늘이 항상 움직이기 때문에","vector":{"논리 사고력":-5,"비문학 배경지식":-5},"error_path":"움직임 자체를 원인으로 오해"},{"choice_id":"C","text":"나침반이 아주 가볍기 때문에","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"무게를 원인으로 오해"},{"choice_id":"D","text":"나침반에 전기가 통하기 때문에","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"전자기력과 자력을 혼동"},{"choice_id":"E","text":"나침반이 빛을 내기 때문에","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"전혀 관계없는 현상을 원인으로 추측"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q08', 'S1_NON_P4', 'sohssure', '논리추론형', '냉장고 문 고무 패킹 안에 자석을 넣은 이유는 무엇일까요?', NULL, 'A', '[{"choice_id":"A","text":"문이 저절로 열리지 않고 꽉 닫히게 하려고","vector":{"논리 사고력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"냉장고 안을 시원하게 하려고","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"냉장고의 주 기능(냉각)을 자석의 기능으로 오해"},{"choice_id":"C","text":"전기를 아끼기 위해서","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"결과적인 효과(절전)를 직접적인 목적으로 오해"},{"choice_id":"D","text":"냉장고 문을 가볍게 만들려고","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"무게 조절을 목적으로 오해"},{"choice_id":"E","text":"음식을 오랫동안 보관하려고","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"냉장고의 목적을 자석의 목적으로 오해"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q09', 'S1_NON_P4', 'sohssure', '논리추론형', '자석이 서로 밀어내는 경우는 언제인가요?', NULL, 'A', '[{"choice_id":"A","text":"N극과 N극이 만났을 때","vector":{"논리 사고력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"N극과 S극이 만났을 때","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"반대 상황(인력) 선택"},{"choice_id":"C","text":"자석이 철에 붙었을 때","vector":{"비문학 배경지식":-5,"논리 사고력":-5},"error_path":"붙는 성질과 혼동"},{"choice_id":"D","text":"자석이 공기 중에 있을 때","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"무관한 조건(매질-공기) 선택"},{"choice_id":"E","text":"자석이 물속에 있을 때","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"무관한 조건(매질-물) 선택"}]', NULL, NULL, NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('S1_NON_P4_Q10', 'S1_NON_P4', 'sohssure', '논리추론형', '이 글로 알 수 있는 내용이 아닌 것은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"자석을 자르면 극이 사라진다","vector":{"문장 독해력":10,"비문학 배경지식":10},"error_path":"정답 (지문에 없는 내용이며 사실과도 다름)"},{"choice_id":"B","text":"자석은 같은 극끼리 밀어낸다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 전제 누락"},{"choice_id":"C","text":"자석은 다른 극끼리 끌어당긴다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 인과 관계 왜곡"},{"choice_id":"D","text":"나침반은 자석의 성질을 이용한다","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"부정형 문항 오독: 조건 혼동"},{"choice_id":"E","text":"우리 생활 주변에 자석이 많이 쓰인다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 범위 과확대"}]', NULL, NULL, NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_Q01', 'F1_LIT_P1', 'frege', '지문근거형', '수남이가 고급 승용차에 흠집을 낸 까닭은 무엇인가요?', NULL, 'A', '[{"choice_id":"A","text":"바람이 불어 자전거가 넘어졌기 때문에","vector":{"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"주인 영감이 밀었기 때문에","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"사건의 인과관계를 왜곡"},{"choice_id":"C","text":"자전거를 타고 너무 빨리 달렸기 때문에","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"본문에 없는 과속을 원인으로 오해"},{"choice_id":"D","text":"빗길에 미끄러졌기 때문에","vector":{"비문학 배경지식":-5,"문장 독해력":-5},"error_path":"날씨(바람 vs 비) 정보를 혼동"},{"choice_id":"E","text":"일부러 차를 발로 찼기 때문에","vector":{"문장 독해력":-5,"국어 개념 적용 능력":-5},"error_path":"고의성 유무를 오판"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_Q02', 'F1_LIT_P1', 'frege', '논리추론형', '수남이가 자전거를 들고 도망친 직접적인 계기는 무엇인가요?', NULL, 'B', '[{"choice_id":"A","text":"아버지에게 혼날 것이 무서워서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"도망친 후의 심리와 계기를 혼동"},{"choice_id":"B","text":"구경하던 사람들의 외침을 듣고","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"C","text":"배달 시간이 늦어서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"사건의 본질적 원인을 파악하지 못함"},{"choice_id":"D","text":"주인 영감이 때리려고 해서","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"지문에 없는 내용 추측"},{"choice_id":"E","text":"돈을 가지러 집에 가기 위해서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"도망의 목적을 오해(해결 vs 회피)"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_Q03', 'F1_LIT_P1', 'frege', '어휘단독형', '다음 문장의 빈칸에 들어갈 낱말로 알맞은 것은 무엇입니까?', '수남이는 그 일 때문에 (          ) 동안 잠을 못 잤다.', 'A', '[{"choice_id":"A","text":"며칠","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}},{"choice_id":"B","text":"며 칠","error_path":"잘못된 띄어쓰기","vector":{"어법·문법 능력":-5,"어휘력":-3}},{"choice_id":"C","text":"몇 일","error_path":"잘못된 표기 (매우 흔한 오류)","vector":{"어법·문법 능력":-3,"어휘력":-3}},{"choice_id":"D","text":"몇일","error_path":"틀린 표기","vector":{"어법·문법 능력":-3,"어휘력":-3}},{"choice_id":"E","text":"면일","error_path":"없는 말","vector":{"어법·문법 능력":-5,"어휘력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_Q04', 'F1_LIT_P1', 'frege', '논리추론형', '수남이의 심장이 터질 것 같았던 이유로 가장 적절한 것은?', NULL, 'D', '[{"choice_id":"A","text":"주인 영감과 싸워서 이겼기 때문에","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"상황 파악 오류 (싸움 승패와 무관)"},{"choice_id":"B","text":"자전거가 너무 무거워서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"심리적 원인을 물리적 원인으로 오해"},{"choice_id":"C","text":"아버지에게 칭찬받을 생각이 나서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"상황의 결과 예측 오류"},{"choice_id":"D","text":"도둑질을 했다는 죄책감과 두려움 때문에","vector":{"문장 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"E","text":"돈을 벌 수 있어서 기뻤기 때문에","vector":{"문장 독해력":-5,"국어 개념 적용 능력":-5},"error_path":"인물의 심리(기쁨)를 정반대로 파악"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_Q05', 'F1_LIT_P1', 'frege', '지문근거형', '차 주인이 수남이에게 요구한 수리비는 얼마인가요?', NULL, 'A', '[{"choice_id":"A","text":"오천 원","vector":{"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"천 원","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"수치 정보 축소 해석"},{"choice_id":"C","text":"일만 원","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"실제 요구 금액의 두 배로 오해"},{"choice_id":"D","text":"십만 원","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"터무니없이 큰 액수로 과장"},{"choice_id":"E","text":"오만 원","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"자릿수(0 하나 더함) 혼동"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_Q06', 'F1_LIT_P1', 'frege', '논리추론형', '구경하던 사람들이 수남이에게 한 말의 의도로 적절한 것은?', NULL, 'C', '[{"choice_id":"A","text":"수남이가 자전거를 훔치도록 부추기려는 악의","vector":{"논리 사고력":-5,"국어 개념 적용 능력":-5},"error_path":"사람들의 행동 동기를 순수 악의로 해석"},{"choice_id":"B","text":"자전거가 본인들의 것이라고 주장하기 위해","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문에 없는 내용 추측"},{"choice_id":"C","text":"작은 실수에 과한 돈을 요구하는 차 주인에 대한 반감","vector":{"논리 사고력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"D","text":"차 주인과 친하기 때문에 장난을 친 것","vector":{"문장 독해력":-5,"국어 개념 적용 능력":-5},"error_path":"관계 파악 오류"},{"choice_id":"E","text":"수남이를 경찰에 신고하기 위해서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"상황과 정반대의 의도 추측"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_Q07', 'F1_LIT_P1', 'frege', '어휘단독형', '\'쿵쾅거리는 소리\'가 의미하는 것은 무엇인가요?', NULL, 'E', '[{"choice_id":"A","text":"공사장에서 나는 소음","vector":{"국어 관련 배경지식":-5,"논리 사고력":-5},"error_path":"지문과 무관한 외부 소음 선택"},{"choice_id":"B","text":"자전거 바퀴가 굴러가는 소리","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"물리적 소음과 심리적 소리 혼동"},{"choice_id":"C","text":"천둥이 치는 소리","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"비유적 표현(벼락같이)과 혼동"},{"choice_id":"D","text":"주인 영감이 발을 구르는 소리","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"주체의 행동 오해"},{"choice_id":"E","text":"두려움과 긴장으로 심장이 뛰는 소리","vector":{"어휘력":10,"문장 독해력":10},"error_path":"정답"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_Q08', 'F1_LIT_P1', 'frege', '지문근거형', '수남이가 집에 돌아왔을 때, 아버지는 어떤 반응을 보였나요?', NULL, 'D', '[{"choice_id":"A","text":"아무 말 없이 방으로 들어갔다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문 내용(질문함)과 불일치"},{"choice_id":"B","text":"수남이를 크게 꾸짖으며 때렸다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"나타나지 않은 행동(체벌) 추측"},{"choice_id":"C","text":"경찰서에 신고하러 나갔다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문에 없는 내용 추측"},{"choice_id":"D","text":"수남이의 얼굴을 물끄러미 바라보며 물었다","vector":{"문장 독해력":10},"error_path":"정답"},{"choice_id":"E","text":"자전거를 잘 가져왔다고 칭찬했다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"상황과 어울리지 않는 반응 선택"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_Q09', 'F1_LIT_P1', 'frege', '서술형', '수남이가 어쩔 줄 몰라 할 때, 구경하던 사람들은 수남이에게 뭐라고 소리쳤는지 쓰시오.', NULL, NULL, '[]', '"얘, 도망가라! 그깟 흠집 가지고 무슨 오천 원이냐? 그냥 자전거 타고 도망가!"', '[{"criteria_id":1,"condition":"도망가라는 말을 씀","score":10,"vector":{"문장 독해력":10,"논리 사고력":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_Q10', 'F1_LIT_P1', 'frege', '서술형', '수남이가 아버지에게 사실대로 말하지 못하고 이불을 뒤집어쓴 이유는 무엇인지 쓰시오.', NULL, NULL, '[]', '아버지 앞에서 도둑질을 했다는 사실을 말하기가 두려웠기 때문입니다.', '[{"criteria_id":1,"condition":"도둑질을 했다는 사실이나 두려움을 언급함","score":10,"vector":{"문장 독해력":10,"논리 사고력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P3_Q01', 'F1_LIT_P3', 'frege', '논리추론형', '소년이 조약돌을 집어 주머니에 넣은 행동의 이유는 무엇일까요?', NULL, 'C', '[{"choice_id":"A","text":"소녀에게 다시 던지려고","vector":{"문장 독해력":-5},"error_path":"공격적인 의도로 해석"},{"choice_id":"B","text":"실수로 주머니에 넣어서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"의도적인 행동을 우연으로 해석"},{"choice_id":"C","text":"소녀에 대한 관심과 그리움을 간직하고 싶어서","vector":{"문장 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"D","text":"돌을 모으는 취미가 있어서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"등장인물의 성격과 무관한 단순 취미로 해석"},{"choice_id":"E","text":"조약돌이 아주 예쁘게 생겨서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"대상의 외적 가치에만 집중"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P3_Q02', 'F1_LIT_P3', 'frege', '지문근거형', '소년이 소녀를 기다리는 동안의 심정 변화를 잘 나타낸 문장은?', NULL, 'B', '[{"choice_id":"A","text":"유난히 맑은 가을 햇살 (기쁨) -> 소녀 아닌 갈꽃 (실망)","vector":{"문장 독해력":-5,"국어 개념 적용 능력":-5},"error_path":"배경 묘사를 심리 변화로 잘못 연결"},{"choice_id":"B","text":"이제 저쯤 갈밭머리로 소녀가 나타나리라. (기대) -> 그런데도 소녀는 나타나지 않는다. (초조)","vector":{"문장 독해력":10,"국어 개념 적용 능력":10},"error_path":"정답"},{"choice_id":"C","text":"학교에서는 쉬는 시간에 운동장을 살폈다. (무관심) -> 남몰래 5학년 여자 반을 엿보기도 했다. (호기심)","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"살피는 행동을 무관심으로 잘못 해석"},{"choice_id":"D","text":"물기가 걷혀 있었다. (허무) -> 조약돌을 집어 주머니에 넣었다. (후회)","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"감정 해석 오류"},{"choice_id":"E","text":"이 바보. (분노) -> 소년은 저도 모르게 벌떡 일어섰다. (놀람)","vector":{"문장 독해력":-5,"국어 개념 적용 능력":-5},"error_path":"기다리는 상황이 아닌 이전 장면 선택"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P3_Q03', 'F1_LIT_P3', 'frege', '어휘단독형', '다음 문장의 빈칸에 들어갈 말로 알맞은 것은 무엇입니까?', '소녀를 만날 생각에 가슴이 (          ).', 'A', '[{"choice_id":"A","text":"설레었다","error_path":"정답","vector":{"어법·문법 능력":10,"어휘력":10}},{"choice_id":"B","text":"설레였다","error_path":"\'설레었다\'의 잘못된 표기","vector":{"어법·문법 능력":-3,"어휘력":-3}},{"choice_id":"C","text":"설레엤다","error_path":"표기 오류","vector":{"어법·문법 능력":-5,"어휘력":-5}},{"choice_id":"D","text":"설레이었다","error_path":"\'설레이다\'는 비표준어 (흔한 오류)","vector":{"어법·문법 능력":-3,"어휘력":-3}},{"choice_id":"E","text":"설렛다","error_path":"표기 오류 (받침 실수)","vector":{"어법·문법 능력":-5,"어휘력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P3_Q04', 'F1_LIT_P3', 'frege', '논리추론형', '\'소녀 아닌 갈꽃이 들길을 걸어오는 것만 같았다\'라는 표현의 효과로 가장 적절한 것은?', NULL, 'B', '[{"choice_id":"A","text":"소녀가 걷는 속도가 매우 빠르다는 것을 강조한다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 전제 누락"},{"choice_id":"B","text":"소녀와 자연이 하나가 된 듯한 아름답고 신비로운 분위기를 준다","vector":{"국어 개념 적용 능력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"C","text":"소년이 시력이 좋지 않다는 것을 암시한다","vector":{"논리 사고력":-5,"국어 개념 적용 능력":-5},"error_path":"부정형 문항 오독: 인과 관계 왜곡"},{"choice_id":"D","text":"가을 날씨가 매우 춥다는 것을 보여준다","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"부정형 문항 오독: 조건 혼동"},{"choice_id":"E","text":"소녀의 옷차림이 화려하다는 것을 나타낸다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 범위 과확대"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P3_Q05', 'F1_LIT_P3', 'frege', '논리추론형', '소녀가 던진 말을 \'이 바보\'라고 한 것에서 알 수 있는 소녀의 마음은?', NULL, 'C', '[{"choice_id":"A","text":"자신의 조약돌을 주워 달라는 명령","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"명령형 어조로 오해"},{"choice_id":"B","text":"아무 이유 없이 지나가는 사람에게 시비를 거는 태도","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"상황 맥락을 무시하고 공격성으로 해석"},{"choice_id":"C","text":"자신을 알아보지 못하거나 다가오지 않는 소년에 대한 서운함과 관심","vector":{"국어 개념 적용 능력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"D","text":"소년이 정말로 지능이 낮다고 생각하는 무시","vector":{"문장 독해력":-5},"error_path":"단어의 사전적 의미로만 해석"},{"choice_id":"E","text":"소년과 싸우고 싶어 하는 적대감","vector":{"문장 독해력":-5},"error_path":"반어적 표현을 직설적 적대감으로 해석"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P3_Q06', 'F1_LIT_P3', 'frege', '지문근거형', '이 글의 시간적, 공간적 배경으로 알맞은 것은?', NULL, 'D', '[{"choice_id":"A","text":"겨울, 눈 덮인 산","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"계절과 장소 불일치"},{"choice_id":"B","text":"여름, 해수욕장","vector":{"문장 독해력":-5,"비문학 배경지식":-5},"error_path":"계절(가을 햇살)과 장소 불일치"},{"choice_id":"C","text":"봄, 꽃이 핀 학교 운동장","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"운동장이 언급되나 주된 배경 아님"},{"choice_id":"D","text":"가을, 갈밭(갈대밭)과 개울가","vector":{"문장 독해력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"E","text":"밤, 어두운 골목길","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"시간(햇살)과 장소 불일치"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P3_Q07', 'F1_LIT_P3', 'frege', '어휘단독형', '\'나풀거리며\'와 느낌이 비슷한 말은?', NULL, 'C', '[{"choice_id":"A","text":"비틀비틀","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"쓰러질 듯 걷는 모양과 혼동"},{"choice_id":"B","text":"쿵쿵거리며","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"무거운 느낌의 의태어 혼동"},{"choice_id":"C","text":"하늘거리며","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"D","text":"살금살금","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"몰래 움직이는 모양과 혼동"},{"choice_id":"E","text":"버럭버럭","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"소리를 지르는 모양과 혼동"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P3_Q08', 'F1_LIT_P3', 'frege', '지문근거형', '다음 날부터 소년이 한 행동으로 알맞지 않은 것은?', NULL, 'E', '[{"choice_id":"A","text":"쉬는 시간에 운동장을 살폈다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 지문 근거 누락"},{"choice_id":"B","text":"주머니 속 조약돌을 만지작거렸다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 세부 정보 오독"},{"choice_id":"C","text":"5학년 여자 반을 엿보았다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 핵심 정보 혼동"},{"choice_id":"D","text":"매일같이 개울가로 달려가 보았다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 과도한 일반화"},{"choice_id":"E","text":"소녀의 집 앞에 찾아가 문을 두드렸다","vector":{"문장 독해력":10},"error_path":"정답"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P3_Q09', 'F1_LIT_P3', 'frege', '서술형', '소년이 소녀가 던진 조약돌을 주워 주머니에 넣은 것은 소녀에 대해 어떤 마음이 있었기 때문인지 쓰시오.', NULL, NULL, '[]', '소녀를 좋아하거나 보고 싶어 하는 마음 (관심)', '[{"criteria_id":1,"condition":"좋아함, 보고 싶음, 관심 등 긍정적 마음을 씀","score":10,"vector":{"문장 독해력":10,"논리 사고력":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P3_Q10', 'F1_LIT_P3', 'frege', '서술형', '소년은 멀리서 걸어오는 소녀의 모습을 무엇 같다고 생각했는지 지문에서 찾아 쓰시오.', NULL, NULL, '[]', '소녀 아닌 갈꽃 (또는 움직이는 갈꽃)', '[{"criteria_id":1,"condition":"\'갈꽃\'이라는 단어를 포함함","score":10,"vector":{"문장 독해력":10,"어휘력":10}}]', NULL, 10);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P5_Q01', 'F1_LIT_P5', 'frege', '지문근거형', '이 글에 등장하는 인물 간의 관계에 대한 설명으로 알맞은 것은?', NULL, 'B', '[{"choice_id":"A","text":"외할머니는 아저씨의 어머니이다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"가족 관계 오해"},{"choice_id":"B","text":"아저씨는 \'나(옥희)\'의 아버지와 친한 친구 사이였다","vector":{"문장 독해력":10,"국어 관련 배경지식":10},"error_path":"정답"},{"choice_id":"C","text":"옥희는 어머니보다 아저씨를 더 좋아한다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"우선순위 오해(어머니 > 아저씨)"},{"choice_id":"D","text":"옥희는 아저씨를 매우 싫어한다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"감정을 정반대로 해석(좋아한다고 답함)"},{"choice_id":"E","text":"아저씨는 옥희의 친아버지이다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"관계를 오해(아버지는 돌아가심)"}]', NULL, NULL, NULL, 1);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P5_Q02', 'F1_LIT_P5', 'frege', '지문근거형', '옥희의 아버지가 지금 계시지 않은 이유는?', NULL, 'E', '[{"choice_id":"A","text":"아저씨와 싸우고 집을 나가서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 지문 근거 누락"},{"choice_id":"B","text":"병원에 입원해 있어서","vector":{"문장 독해력":-5,"국어 관련 배경지식":-5},"error_path":"부정형 문항 오독: 세부 정보 오독"},{"choice_id":"C","text":"돈을 벌러 멀리 떠나서","vector":{"문장 독해력":-5,"국어 관련 배경지식":-5},"error_path":"부정형 문항 오독: 핵심 정보 혼동"},{"choice_id":"D","text":"외할머니 댁에 가 있어서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"부정형 문항 오독: 과도한 일반화"},{"choice_id":"E","text":"옥희가 태어나기도 전에 세상을 떠나서","vector":{"문장 독해력":10},"error_path":"정답"}]', NULL, NULL, NULL, 2);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P5_Q03', 'F1_LIT_P5', 'frege', '어휘단독형', '다음 <보기>의 문장에서 밑줄 친 \'친절했다\'의 품사는 무엇입니까?', '<보기>\n아저씨는 나에게 참 친절했다.', 'C', '[{"choice_id":"A","text":"부사","error_path":"역할 혼동","vector":{"어법·문법 능력":-4,"국어 개념 적용 능력":-4}},{"choice_id":"B","text":"관형사","error_path":"문법 규칙 오해","vector":{"어법·문법 능력":-4,"국어 개념 적용 능력":-4}},{"choice_id":"C","text":"형용사","error_path":"정답","vector":{"어법·문법 능력":10,"국어 개념 적용 능력":10}},{"choice_id":"D","text":"동사","error_path":"형용사와 동사 구별 실패 (개념 혼동)","vector":{"어법·문법 능력":-3,"국어 개념 적용 능력":-3}},{"choice_id":"E","text":"명사","error_path":"명확한 오답 (기본 개념 미숙)","vector":{"어법·문법 능력":-5,"국어 개념 적용 능력":-5}}]', NULL, NULL, NULL, 3);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P5_Q04', 'F1_LIT_P5', 'frege', '논리추론형', '이 글의 서술자(말하는 사람)인 \'나\'에 대한 설명으로 옳은 것은?', NULL, 'A', '[{"choice_id":"A","text":"순수한 어린아이의 시선으로 이야기를 전달하고 있다","vector":{"국어 개념 적용 능력":10,"문장 독해력":10},"error_path":"정답"},{"choice_id":"B","text":"매우 분석적이고 비판적인 성인 남성이다","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"어투(옥희야, ~했어)와 맞지 않음"},{"choice_id":"C","text":"이야기 속에 등장하지 않고 관찰만 하는 사람이다","vector":{"국어 개념 적용 능력":-5,"논리 사고력":-5},"error_path":"3인칭 관찰자 시점과 혼동"},{"choice_id":"D","text":"작가가 직접 자신의 이야기를 하고 있다","vector":{"국어 개념 적용 능력":-5,"국어 관련 배경지식":-5},"error_path":"수필이나 자서전으로 오해"},{"choice_id":"E","text":"모든 사건을 꿰뚫어 보는 전지전능한 신과 같은 존재이다","vector":{"국어 개념 적용 능력":-5,"논리 사고력":-5},"error_path":"전지적 작가 시점과 혼동"}]', NULL, NULL, NULL, 4);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P5_Q05', 'F1_LIT_P5', 'frege', '논리추론형', '아저씨가 옥희를 안아주고 뺨에 입을 맞춘 이유는 무엇일까요?', NULL, 'E', '[{"choice_id":"A","text":"옥희에게 부탁할 일이 있어서","vector":{"문장 독해력":-5},"error_path":"계산적인 의도로 해석"},{"choice_id":"B","text":"옥희가 울면서 떼를 썼기 때문에","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문 상황(갑자기 서러워짐)의 왜곡"},{"choice_id":"C","text":"옥희가 노래를 잘 불렀기 때문에","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문에 없는 행동을 근거로 추측"},{"choice_id":"D","text":"자신의 친구인 옥희 아버지를 닮지 않아서","vector":{"논리 사고력":-5,"문장 독해력":-5},"error_path":"맥락과 모순(친구의 딸이라 아낌)"},{"choice_id":"E","text":"아버지가 없는 옥희에 대한 연민과 사랑스러움 때문에","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"}]', NULL, NULL, NULL, 5);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P5_Q06', 'F1_LIT_P5', 'frege', '논리추론형', '이 글에서 \'하늘나라\'가 상징하는 의미는?', NULL, 'C', '[{"choice_id":"A","text":"비행기","vector":{"문장 독해력":-5,"어휘력":-5},"error_path":"하늘과 관련된 탈것으로 연상"},{"choice_id":"B","text":"해외여행","vector":{"문장 독해력":-5,"국어 관련 배경지식":-5},"error_path":"문자 그대로의 여행지로 해석"},{"choice_id":"C","text":"죽음","vector":{"국어 개념 적용 능력":10,"어휘력":10},"error_path":"정답"},{"choice_id":"D","text":"높은 산꼭대기","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"물리적 높이로 해석"},{"choice_id":"E","text":"꿈속 세상","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"환상적인 공간으로 해석"}]', NULL, NULL, NULL, 6);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P5_Q07', 'F1_LIT_P5', 'frege', '논리추론형', '옥희가 \'갑자기 서러워진\' 이유는 무엇일까요?', NULL, 'B', '[{"choice_id":"A","text":"외할머니가 무서운 이야기를 해서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"회상 내용(아버지 죽음)을 무서운 이야기로 오해"},{"choice_id":"B","text":"아버지가 돌아가셔서 다시는 볼 수 없다는 사실을 깨달아서","vector":{"문장 독해력":10,"논리 사고력":10},"error_path":"정답"},{"choice_id":"C","text":"배가 고픈데 밥을 주지 않아서","vector":{"국어 관련 배경지식":-5,"논리 사고력":-5},"error_path":"생리적 욕구로 단순화"},{"choice_id":"D","text":"어머니가 보고 싶어서","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"대상(아버지 -> 어머니) 혼동"},{"choice_id":"E","text":"아저씨가 옥희를 혼냈기 때문에","vector":{"문장 독해력":-5,"논리 사고력":-5},"error_path":"지문 내용과 반대(다정하게 대함)"}]', NULL, NULL, NULL, 7);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P5_Q08', 'F1_LIT_P5', 'frege', '지문근거형', '옥희는 \'누가 제일 좋으냐\'는 아저씨의 질문에 누구라고 대답했나요?', NULL, 'E', '[{"choice_id":"A","text":"아범(아버지)","vector":{"문장 독해력":-5},"error_path":"대화의 주제였으나 대답은 아님"},{"choice_id":"B","text":"아저씨","vector":{"문장 독해력":-5},"error_path":"두 번째로 좋다고 한 사람임"},{"choice_id":"C","text":"외할머니","vector":{"문장 독해력":-5},"error_path":"지문에 언급되었으나 대답은 아님"},{"choice_id":"D","text":"선생님","vector":{"문장 독해력":-5,"국어 관련 배경지식":-5},"error_path":"지문에 없는 인물"},{"choice_id":"E","text":"어머니","vector":{"문장 독해력":10},"error_path":"정답"}]', NULL, NULL, NULL, 8);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P5_Q09', 'F1_LIT_P5', 'frege', '서술형', '옥희가 갑자기 서러워진 이유를 서술하시오. (30자 내외)', NULL, NULL, '[]', '아버지가 세상을 떠나 다시 만날 수 없다는 사실이 서러웠기 때문이다.', '[{"criteria_id":1,"condition":"아버지가 세상을 떠났다는 사실(하늘나라로 감)을 언급함","score":5,"vector":{"문장 독해력":10}},{"criteria_id":2,"condition":"다시 만날 수 없어 서러워졌다는 정서를 서술함","score":5,"vector":{"논리 사고력":10}}]', NULL, 9);
INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_LIT_P5_Q10', 'F1_LIT_P5', 'frege', '서술형', '아저씨가 옥희를 안아 올리고 뺨에 입맞춘 행동이 드러내는 태도를 서술하시오. (30자 내외)', NULL, NULL, '[]', '아버지 없는 옥희를 안쓰럽게 여기며 따뜻하게 위로하고 사랑하는 태도이다.', '[{"criteria_id":1,"condition":"옥희를 안쓰럽게 여기는 태도를 언급함","score":5,"vector":{"문장 독해력":10}},{"criteria_id":2,"condition":"따뜻한 위로/사랑의 태도를 서술함","score":5,"vector":{"논리 사고력":10}}]', NULL, 10);
