INSERT INTO diag_questions (id, passage_id, tier, question_type, stem, box_content, correct_choice, choices_json, model_answer, grading_criteria_json, pair_id, order_in_passage) VALUES ('F1_NON_P5_Q04', 'F1_NON_P5', 'frege', '어휘단독형', '\'비롯되었다\'와 바꿔 쓰기에 가장 적절한 말은?', NULL, 'A', '[{"choice_id":"A","text":"시작되었다","vector":{"어휘력":10},"error_path":"정답"},{"choice_id":"B","text":"발견되었다","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"찾아냈다는 의미로 오해"},{"choice_id":"C","text":"변화되었다","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"바뀌었다는 의미로 오해"},{"choice_id":"D","text":"마무리되었다","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"반대말(끝났다) 선택"},{"choice_id":"E","text":"사라졌다","vector":{"어휘력":-5,"문장 독해력":-5},"error_path":"없어졌다는 의미로 오해"}]', NULL, NULL, NULL, 4);
